// Auto-generated tutor knowledge base from Chapter 8 AI Reference Documents
// Part 1 + Part 2 + synthetic overviews — parsed into topical chunks for client-side RAG
const TUTOR_KNOWLEDGE_BASE = [{"heading": "Overview: What is Radioactive Decay?", "body": "Radioactive decay is the process by which an unstable atomic nucleus loses energy by emitting radiation. A nucleus that is unstable because it has too many protons, too many neutrons, or too much energy will spontaneously transform into a more stable configuration by emitting particles or photons.\n\nThe five main types of radioactive decay are:\n1. **Alpha decay (α)** — emission of a helium-4 nucleus (2 protons + 2 neutrons)\n2. **Beta-minus decay (β⁻)** — a neutron converts to a proton, emitting an electron and antineutrino\n3. **Beta-plus decay (β⁺)** — a proton converts to a neutron, emitting a positron and neutrino\n4. **Electron capture (EC)** — a proton captures an inner orbital electron, converting to a neutron\n5. **Gamma emission (γ)** — emission of a high-energy photon from an excited nucleus\n\nRadioactive decay is a random process at the level of individual atoms, but for large samples it follows predictable statistical laws described by the exponential decay equation: N(t) = N₀e^(−λt). The half-life (t½) is the time required for half the radioactive nuclei in a sample to decay.", "keywords": ["radioactive decay", "radioactivity", "what is radioactive decay", "unstable nucleus", "emission", "radiation", "alpha decay", "beta decay", "gamma emission", "half-life", "exponential decay"], "source": "Synthesis"}, {"heading": "Overview: Why Do Nuclei Decay?", "body": "Nuclei decay because they are unstable — the balance between the attractive strong nuclear force and the repulsive electromagnetic (Coulomb) force is disrupted.\n\nOf approximately 3,300 known nuclides, only about 279 are stable. The rest are radioactive and will eventually decay toward more stable configurations.\n\nKey reasons for instability:\n- **Too many protons**: Coulomb repulsion scales as Z(Z−1) and becomes overwhelming in heavy nuclei\n- **Wrong neutron-to-proton ratio**: The optimal N/Z ratio increases from ~1.0 for light elements to ~1.5 for heavy elements near lead\n- **Odd-odd configuration**: Nuclei with odd numbers of both protons and neutrons are less stable (only 4 stable odd-odd nuclei exist: ¹H, ⁶Li, ¹⁰B, ¹⁴N)\n- **Excess energy**: Even stable nuclei can be created in excited states that decay via gamma emission\n\nThe strong nuclear force binds nucleons together but has a very short range (~1–3 fm). Beyond this range, the infinite-range Coulomb repulsion between protons dominates, making heavy nuclei inherently unstable.", "keywords": ["why do nuclei decay", "unstable", "instability", "strong force", "coulomb", "n/z ratio", "odd-odd"], "source": "Synthesis"}, {"heading": "Overview: What is the Valley of Stability?", "body": "The valley of stability is a curved band on a plot of neutron number (N) versus proton number (Z) where stable isotopes cluster. It is one of the most important concepts in nuclear physics for predicting decay modes.\n\nKey features:\n- For light elements (Z ≤ 20), stable isotopes lie near the N = Z line\n- For heavier elements, the valley curves toward the neutron-rich side (N > Z) because extra neutrons are needed to offset growing Coulomb repulsion\n- No stable isotopes exist for elements beyond bismuth (Z = 83)\n\nPredicting decay from position:\n- **Above the valley** (too many neutrons): undergo β⁻ decay → converts neutron to proton\n- **Below the valley** (too many protons): undergo β⁺ decay or electron capture → converts proton to neutron\n- **Far below, heavy nucleus**: undergo α decay → reduces both N and Z by 2\n- **On the valley but excited**: undergo γ emission → releases excess energy only\n\nThe valley ends at lead (Z = 82), beyond which all isotopes are radioactive. Some very heavy isotopes like uranium-238 have half-lives comparable to Earth's age (~4.5 billion years) and are still found in nature.", "keywords": ["valley of stability", "valley", "band of stability", "n-z plot", "predict decay", "above valley", "below valley"], "source": "Synthesis"}, {"heading": "Overview: Nuclear Forces and Stability", "body": "Three fundamental forces govern nuclear behavior:\n\n1. **Strong nuclear force** — binds protons and neutrons together. It is ~100× stronger than electromagnetism at distances of ~1 fm, but has a very short range (~1–3 fm). It acts equally between all nucleon pairs (p-p, n-n, p-n). Below ~0.5 fm it becomes repulsive (the \"hard core\"), preventing nuclear collapse.\n\n2. **Electromagnetic force** — causes Coulomb repulsion between protons. It is infinite-range and scales as Z(Z−1), meaning the total repulsion grows rapidly as more protons are added. This is why heavy nuclei need extra neutrons.\n\n3. **Weak nuclear force** — mediates beta decay by converting protons to neutrons and vice versa. It is ~10⁶ times weaker than the strong force and has an extremely short range (~0.001 fm). It is the only force that can change quark flavour.\n\n**Root cause of instability**: The strong force is short-range and saturates (each nucleon only interacts with nearest neighbours), while Coulomb repulsion is long-range and grows without limit. When Coulomb repulsion exceeds the binding capacity of the strong force, the nucleus becomes unstable and decays.", "keywords": ["strong force", "coulomb", "weak force", "nuclear forces", "electromagnetic", "repulsion", "binding"], "source": "Synthesis"}, {"heading": "Overview: Half-Life and Activity", "body": "Radioactive decay follows **first-order kinetics**: the rate of decay is proportional to the number of radioactive nuclei present.\n\n**Key equations:**\n- N(t) = N₀ e^(−λt)  — number of nuclei remaining after time t\n- t½ = ln(2) / λ ≈ 0.693 / λ  — half-life in terms of decay constant\n- A = λN  — activity (decays per second), measured in becquerels (Bq)\n- 1 curie (Ci) = 3.70 × 10¹⁰ Bq\n\n**Important properties:**\n- Half-life is an intrinsic nuclear property — it does NOT depend on temperature, pressure, chemical environment, or sample age\n- After n half-lives, the fraction remaining is (1/2)ⁿ\n- Mean lifetime τ = 1/λ = t½ / ln(2) ≈ 1.443 × t½\n\n**Example half-lives:**\n- Carbon-14: 5,730 years (radiocarbon dating)\n- Uranium-238: 4.47 × 10⁹ years (geological dating)\n- Technetium-99m: 6.0 hours (nuclear medicine)\n- Polonium-212: 0.3 microseconds (fastest alpha emitter)", "keywords": ["half-life", "activity", "decay constant", "lambda", "exponential decay", "becquerel", "curie", "mean lifetime"], "source": "Synthesis"}, {"heading": "Overview: Applications of Radioactivity", "body": "Radioactivity has numerous important applications across medicine, industry, and science:\n\n**Nuclear Medicine:**\n- **Technetium-99m** (t½ = 6 h, γ emitter): used in ~80% of nuclear medicine scans for imaging bones, heart, and other organs\n- **Fluorine-18** (t½ = 110 min, β⁺ emitter): used in PET scanning to detect cancers by imaging metabolic activity\n- **Iodine-131** (t½ = 8 days, β⁻ + γ): used to diagnose and treat thyroid conditions\n- **Cobalt-60** (t½ = 5.27 years, β⁻ + γ): used in cancer radiotherapy\n\n**Dating:**\n- **Carbon-14 dating**: measures the remaining ¹⁴C in organic materials up to ~50,000 years old\n- **Uranium-lead dating**: measures the Pb-206/U-238 ratio in rocks for geological timescales (millions to billions of years)\n\n**Other Applications:**\n- **Smoke detectors**: Americium-241 (α emitter) ionises air; smoke reduces ionisation and triggers the alarm\n- **Nuclear power**: Induced fission of U-235 in controlled chain reactions provides ~10% of global electricity\n- **Sterilisation**: Gamma radiation from Co-60 is used to sterilise medical equipment and food", "keywords": ["applications", "nuclear medicine", "pet scan", "tc-99m", "carbon-14 dating", "radiocarbon", "smoke detector", "nuclear power", "reactor"], "source": "Synthesis"}, {"heading": "8.1 — Why Most Nuclei Are Unstable", "body": "- Of ~3,300 known nuclides, only **279 are stable**.\n- All nuclei are held together by the **strong nuclear force**, which acts between all nucleon pairs (p-p, n-n, p-n) at distances of ~1–3 femtometres (fm; 1 fm = 10⁻¹⁵ m).\n- The strong force at 1 fm is ~100× stronger than Coulomb (electromagnetic) repulsion between two individual nucleons.\n- **Critical limitation of the strong force:** it essentially vanishes beyond ~3 fm. It is short-range.\n- **Coulomb repulsion** is long-range (infinite range, falls as 1/r²) and scales as **Z(Z−1)** — the total electromagnetic repulsion grows rapidly as more protons are added.\n- **Root cause of instability:** short-range attraction vs. long-range repulsion. When Coulomb repulsion exceeds the binding capacity of the strong force, the nucleus decays.\n- Stability depends on three numbers: **Z** (proton count), **N** (neutron count), and **A = Z + N** (mass number).", "keywords": ["nuclei", "unstable", "activity", "strong force", "forces"], "source": "Part 1"}, {"heading": "8.2 — The Forces Inside the Nucleus", "body": "- The strong force is **charge independent** — it acts equally on all nucleon pairs.\n- Below ~0.5 fm, the strong force becomes **repulsive** (the \"hard core\"), preventing nucleons from collapsing into each other and giving nuclei definite sizes.\n- **Neutrons' role:** they contribute strong-force binding WITHOUT adding to Coulomb repulsion, which is why heavier stable nuclei need more neutrons than protons.\n- **Lead-208:** 82 protons, 126 neutrons → N/Z ≈ 1.54.\n- **Beyond bismuth (Z = 83):** no stable isotopes exist. All are radioactive.\n- Coulomb repulsion scales as Z(Z−1) — approximately **quadruples each time Z doubles**, which is why the neutron excess must increase rapidly for heavy elements.", "keywords": ["forces", "inside", "nucleus", "strong force", "isotope", "n/z"], "source": "Part 1"}, {"heading": "8.3 — The Valley of Stability", "body": "- A plot of N vs. Z for all stable isotopes produces a curved band called the **valley of stability**.\n- For **Z ≤ 20**, stable isotopes follow approximately **N = Z** (e.g., ¹²C, ¹⁶O, ⁴⁰Ca).\n- For heavier elements, the valley curves toward the **neutron-rich side** (N > Z).\n- **Position predicts decay mode** (see table in Section 3 below).\n- No stable isotopes exist for Z > 83 (bismuth).", "keywords": ["valley", "stability", "valley of stability", "isotope", "radioactive decay"], "source": "Part 1"}, {"heading": "8.4 — What Makes a Nucleus Stable?", "body": "Four key factors:\n1. **N/Z Ratio** — optimal ratio rises from ~1.0 (light elements) to ~1.5 (heavy elements near lead).\n2. **Even-Odd Configuration** — even-even nuclei are most stable; odd-odd are least stable (only 4 stable odd-odd nuclei exist).\n3. **Magic Numbers** — 2, 8, 20, 28, 50, 82, 126 confer exceptional stability (shell model).\n4. **Binding Energy per Nucleon (BE/A)** — higher = more stable; peaks at ⁵⁶Fe at 8.79 MeV/nucleon.", "keywords": ["makes", "nucleus", "stable", "binding energy", "shell model", "dose", "n/z", "pairing"], "source": "Part 1"}, {"heading": "8.5 — How Unstable Nuclei Decay", "body": "Five decay modes: **alpha (α), beta-minus (β⁻), beta-plus (β⁺), electron capture (EC), gamma (γ)**. See Section 3 for complete details.", "keywords": ["unstable", "nuclei", "decay", "beta decay", "radiation", "radioactive decay"], "source": "Part 1"}, {"heading": "8.6 — Decay Chains", "body": "- Heavy nuclei often cannot reach stability in one decay step.\n- They undergo **decay chains** — sequences of α and β⁻ decays until a stable nuclide is reached.\n- **Uranium-238 chain:** 14 steps (8α + 6β⁻), ends at stable **Pb-206**. Half-lives range from 4.47 Gy (U-238) down to 164 μs (Po-214).\n- **Secular equilibrium:** after many daughter half-lives, every daughter's activity equals the parent's activity.", "keywords": ["decay", "chains", "beta decay", "activity", "u-238", "dose", "secular equilibrium"], "source": "Part 1"}, {"heading": "8.7 — Half-Life and Activity", "body": "- Decay follows **first-order kinetics**: N(t) = N₀e^(−λt).\n- **Half-life** (t½) = ln2 / λ = 0.693 / λ.\n- Half-life is independent of temperature, pressure, chemical environment, and sample age.\n- **Activity** A = λN, measured in **becquerels (Bq)** = 1 disintegration per second.\n- Older unit: **curie (Ci)** = 3.70 × 10¹⁰ Bq.", "keywords": ["half", "life", "activity", "half-life", "historical"], "source": "Part 1"}, {"heading": "8.8 — Applications", "body": "- **Nuclear medicine:** Tc-99m (6h half-life, γ emitter) used in ~80% of nuclear medicine scans.\n- **Radiometric dating:** ¹⁴C (5730 y) for organic materials up to ~50,000 years; U-Pb for geological timescales.\n- **PET imaging:** ¹⁸F (β⁺ emitter, 110 min), positron annihilation produces two 511 keV gamma rays.\n- **Nuclear power:** fission of U-235 (not U-238, which is not fissile).\n- **Smoke detectors:** Am-241 (α emitter) ionises air; smoke reduces ionisation and triggers alarm.\n\n---", "keywords": ["applications", "beta decay", "gamma", "half-life", "activity", "u-238", "tc-99m", "pet", "fission", "reactor", "radiation", "dating"], "source": "Part 1"}, {"heading": "Decay Constant and Half-Life", "body": "| Relationship | Formula | Notes |\n|---|---|---|\n| Radioactive decay law | N(t) = N₀ e^(−λt) | N = number of nuclei remaining |\n| Half-life from decay constant | t½ = ln(2) / λ = 0.693 / λ | λ = decay constant (s⁻¹) |\n| Decay constant from half-life | λ = 0.693 / t½ | |\n| Mean lifetime | τ = 1/λ = t½ / ln(2) ≈ 1.443 × t½ | N = N₀e^(−t/τ) |\n| Nuclei remaining after n half-lives | N = N₀ × (1/2)ⁿ | n = t / t½ |\n| Activity | A = λN | Units: Bq (= s⁻¹) |\n| Activity decay | A(t) = A₀ e^(−λt) | Same form as N(t) |", "keywords": ["decay", "constant", "half", "life", "half-life", "activity", "radioactive decay"], "source": "Part 1"}, {"heading": "Q-Value (Energy Released)", "body": "**General:**\n> Q = (mass of reactants − mass of products) × c²\n> Q = Δm × 931.5 MeV/u  (when masses are in atomic mass units)\n\n**Alpha decay specifically:**\n> Q = (m_parent − m_daughter − m_alpha) × 931.5 MeV/u\n\n**Rule:** If Q > 0, decay is energetically possible. If Q < 0, it cannot occur spontaneously.", "keywords": ["value", "energy", "released", "alpha decay", "activity", "radiation"], "source": "Part 1"}, {"heading": "Radiometric Dating Age Equation", "body": "> t = (1/λ) × ln(1 + N_daughter / N_parent)\n\nOr using half-life:\n> t = t½ × log₂(N₀ / N) = t½ × [ln(N₀/N) / ln(2)]\n\n**For activity (when initial activity is known):**\n> t = (t½ / ln2) × ln(A₀ / A)\n\n**Or equivalently:**\n> t = t½ × log₂(A₀ / A) = t½ × n  (where n is number of half-lives elapsed)", "keywords": ["radiometric", "dating", "age", "equation", "half-life", "activity"], "source": "Part 1"}, {"heading": "Geiger-Nuttall Law (Alpha Decay)", "body": "> log₁₀(T½) = A(Z)/√E + B(Z)\n\nThis shows that a small change in decay energy E produces an enormous change in half-life — 20 orders of magnitude difference from a factor-of-2 change in energy (see Po-212 vs U-238 example).", "keywords": ["geiger", "nuttall", "law", "alpha", "decay", "half-life", "u-238", "dose", "exam"], "source": "Part 1"}, {"heading": "Semi-Empirical Mass Formula (SEMF / Weizsäcker Formula)", "body": "> BE = a_v·A − a_s·A^(2/3) − a_c·[Z(Z−1)/A^(1/3)] − a_a·[(N−Z)²/A] ± δ(A)\n\n| Term | Name | Coefficient | Physical meaning |\n|---|---|---|---|\n| a_v·A | Volume | 15.75 MeV | Each nucleon gains constant binding from nearest neighbours |\n| −a_s·A^(2/3) | Surface | 17.8 MeV | Surface nucleons have fewer neighbours |\n| −a_c·Z(Z−1)/A^(1/3) | Coulomb | 0.711 MeV | Electrostatic repulsion between all proton pairs |\n| −a_a·(N−Z)²/A | Asymmetry | 23.7 MeV | Energy penalty when N ≠ Z (Pauli exclusion) |\n| ±δ | Pairing | ±11.18/√A MeV | +δ for even-even; 0 for odd-A; −δ for odd-odd |\n\n**Pairing term sign rule:**\n- Even Z, Even N (even-even): **+δ** (extra stability)\n- Odd A (one even, one odd): **0** (no effect)\n- Odd Z, Odd N (odd-odd): **−δ** (reduced stability)\n\n---", "keywords": ["semi", "empirical", "mass", "formula", "semf", "weizsäcker", "activity", "strong force", "neutrino", "dose", "pairing"], "source": "Part 1"}, {"heading": "Alpha Decay (α)", "body": "- **Emission:** helium-4 nucleus (2 protons + 2 neutrons)\n- **Equation:** ᴬ_Z X → ᴬ⁻⁴_(Z−2) Y + ⁴₂He + Q\n- **Changes:** Z decreases by 2, A decreases by 4, N decreases by 2\n- **Typical Q-value:** 4–9 MeV\n- **When it occurs:** Heavy nuclei, typically Z > 83, A > 210\n- **Mechanism:** Quantum tunnelling through the Coulomb barrier (Gamow, 1928)\n- **Energy spectrum:** Discrete — alpha particles emitted at specific energies\n- **Key insight:** Higher Q → shorter half-life (Geiger-Nuttall law). Po-212 (Qα = 8.95 MeV) has t½ = 0.3 μs; U-238 (Qα = 4.27 MeV) has t½ = 4.47 Gy.", "keywords": ["alpha", "decay", "alpha decay", "half-life", "activity", "strong force", "quantum tunnelling", "u-238", "radiation", "dose", "q-value"], "source": "Part 1"}, {"heading": "Beta-Minus Decay (β⁻)", "body": "- **Emission:** Electron (e⁻) + electron antineutrino (ν̄_e)\n- **Nuclear process:** n → p + e⁻ + ν̄_e\n- **Equation:** ᴬ_Z X → ᴬ_(Z+1) Y + e⁻ + ν̄_e + Q\n- **Changes:** Z increases by 1, A unchanged, N decreases by 1\n- **Typical Q-value:** 0.01–10 MeV\n- **When it occurs:** Neutron-rich nuclei (above the valley of stability)\n- **Force involved:** Weak nuclear force (via W⁻ boson exchange)\n- **Energy spectrum:** Continuous (0 to Q_max) — historically puzzling until Pauli postulated the neutrino in 1930\n- **Effect:** Moves nucleus toward valley of stability by reducing N and increasing Z", "keywords": ["beta", "minus", "decay", "activity", "valley of stability", "neutrino", "dose", "q-value", "forces"], "source": "Part 1"}, {"heading": "Beta-Plus Decay (β⁺)", "body": "- **Emission:** Positron (e⁺) + electron neutrino (ν_e)\n- **Nuclear process:** p → n + e⁺ + ν_e\n- **Equation:** ᴬ_Z X → ᴬ_(Z−1) Y + e⁺ + ν_e + Q\n- **Changes:** Z decreases by 1, A unchanged, N increases by 1\n- **Energy requirement:** Q must exceed **1.022 MeV** (to create the positron mass, 2 × 0.511 MeV)\n- **When it occurs:** Proton-rich nuclei (below valley), typically lighter elements\n- **Application:** Basis of PET scanning (positron annihilates with electron → two 511 keV gamma rays)", "keywords": ["beta", "plus", "decay", "gamma", "valley of stability", "neutrino", "pet", "radiation", "dose", "applications"], "source": "Part 1"}, {"heading": "Electron Capture (EC)", "body": "- **Process:** Nucleus absorbs one of its own inner-shell orbital electrons\n- **Equation:** ᴬ_Z X + e⁻ → ᴬ_(Z−1) Y + ν_e\n- **Changes:** Same as β⁺ (Z−1, A unchanged, N+1)\n- **When it occurs:** Alternative to β⁺ when Q < 1.022 MeV, or competes with β⁺\n- **Signature:** Inner shell vacancy filled by outer electrons → characteristic X-rays of the daughter element\n- **Force involved:** Weak nuclear force", "keywords": ["electron", "capture", "beta decay", "pet", "forces"], "source": "Part 1"}, {"heading": "Gamma Emission (γ)", "body": "- **Emission:** High-energy photon\n- **Equation:** ᴬ_Z X* → ᴬ_Z X + γ\n- **Changes:** None — Z, A, N all unchanged; nucleus just loses excess energy\n- **Typical energies:** keV to several MeV\n- **When it occurs:** After α or β decay leaves daughter in an excited state; usually within 10⁻¹² seconds\n- **Note:** Gamma rays are the most penetrating form of nuclear radiation\n- **Medical example:** Tc-99m decays via γ emission (no change in composition)", "keywords": ["gamma", "emission", "activity", "tc-99m", "radiation", "dose", "exam"], "source": "Part 1"}, {"heading": "Spontaneous Fission", "body": "- **Occurs in:** Very heavy nuclei (Z ≥ 100)\n- **Process:** Nucleus splits into two roughly equal fragments + several neutrons\n- **Competes with:** Alpha decay for elements beyond fermium (Z = 100)\n- **Distinction:** Induced fission (by neutron absorption) is the basis of nuclear reactors", "keywords": ["spontaneous", "fission", "alpha decay", "pet", "reactor", "radiation", "historical"], "source": "Part 1"}, {"heading": "Summary Table — All Decay Modes", "body": "| Decay mode | Emission | ΔZ | ΔA | ΔN | Condition |\n|---|---|---|---|---|---|\n| α | ⁴He nucleus | −2 | −4 | −2 | Heavy nuclei, Z > 83 |\n| β⁻ | e⁻ + ν̄_e | +1 | 0 | −1 | Neutron-rich (above valley) |\n| β⁺ | e⁺ + ν_e | −1 | 0 | +1 | Proton-rich, Q > 1.022 MeV |\n| EC | ν_e only | −1 | 0 | +1 | Proton-rich, alternative to β⁺ |\n| γ | Photon | 0 | 0 | 0 | Excited nucleus |\n| Fission | 2 fragments + n | varies | varies | varies | Z ≥ 100 |", "keywords": ["summary", "table", "decay", "modes", "beta decay", "activity", "valley of stability", "fission", "radioactive decay"], "source": "Part 1"}, {"heading": "Conservation Laws in Decay", "body": "| Quantity | α | β⁻ | β⁺ | EC | γ |\n|---|---|---|---|---|---|\n| Mass number A | Conserved | Conserved | Conserved | Conserved | Conserved |\n| Charge (Z) | −2 | +1 | −1 | −1 | 0 |\n| Baryon number | Conserved | Conserved | Conserved | Conserved | Conserved |\n| Lepton number | 0 | e⁻(+1) + ν̄_e(−1) = 0 | e⁺(−1) + ν_e(+1) = 0 | e⁻(+1) captured + ν_e(−1) = 0 | 0 |\n| Energy | Released as Q | Released as Q | Released if Q > 1.022 MeV | Released as Q | Released as E_γ |\n\n---", "keywords": ["conservation", "laws", "decay", "beta decay", "dose"], "source": "Part 1"}, {"heading": "What it is", "body": "A plot of N (neutron number) vs. Z (proton number) for all known nuclides. Stable isotopes form a curved band — the \"valley.\" Unstable isotopes lie outside it.", "keywords": ["valley of stability", "isotope"], "source": "Part 1"}, {"heading": "N = Z line", "body": "- Light elements (Z ≤ 20): stable isotopes lie near or on N = Z.\n- Examples on N = Z: ¹²C (6,6), ¹⁶O (8,8), ⁴⁰Ca (20,20).", "keywords": ["line", "isotope", "exam"], "source": "Part 1"}, {"heading": "Curvature toward neutron-rich side", "body": "As Z increases, the valley curves upward (N > Z) because extra neutrons are needed to provide additional strong-force binding to offset growing Coulomb repulsion.", "keywords": ["curvature", "toward", "neutron", "rich", "side", "valley of stability", "strong force", "forces"], "source": "Part 1"}, {"heading": "Predicting decay from position", "body": "| Position on N-Z plot | What it means | Decay mode | Effect |\n|---|---|---|---|\n| **Above** the valley | Too many neutrons (N/Z too high) | β⁻ decay | N−1, Z+1 → shifts toward valley |\n| **Below** the valley | Too many protons (N/Z too low) | β⁺ decay or EC | N+1, Z−1 → shifts toward valley |\n| **Far below, heavy nucleus** | Excess protons + large Z | α decay | N−2, Z−2 → moves toward valley |\n| **On valley, excited state** | No excess nucleons, excess energy only | γ emission | No change to N or Z |", "keywords": ["predicting", "decay", "position", "alpha decay", "beta decay", "activity", "valley of stability", "dose", "n/z", "radioactive decay"], "source": "Part 1"}, {"heading": "End of the valley", "body": "- Beyond Bi (Z = 83): no stable isotopes exist.\n- Some radioactive isotopes (e.g., U-238) have half-lives comparable to Earth's age (~4.5 Gy) and are found in nature.\n\n---", "keywords": ["end", "valley", "u-238", "dose", "isotope"], "source": "Part 1"}, {"heading": "Factor 1: N/Z Ratio", "body": "| Z range | Optimal N/Z ratio | Example |\n|---|---|---|\n| Z ≤ 20 | ~1.0 | ¹²C (N/Z = 1.0), ⁴⁰Ca (N/Z = 1.0) |\n| Z = 21–40 | ~1.25 | |\n| Z near 82 | ~1.5 | ²⁰⁸Pb (N/Z = 126/82 ≈ 1.54) |\n| Z > 83 | No stable value | All isotopes radioactive |", "keywords": ["factor", "ratio", "isotope", "n/z", "exam"], "source": "Part 1"}, {"heading": "Factor 2: Even-Odd Configuration (Pairing)", "body": "| Protons (Z) | Neutrons (N) | Number of stable isotopes | Stability |\n|---|---|---|---|\n| Even | Even | 165 | Most stable |\n| Even | Odd | 57 | Moderate |\n| Odd | Even | 50 | Less stable |\n| Odd | Odd | **4 only** (¹H, ⁶Li, ¹⁰B, ¹⁴N) | Least stable |\n\n**Why:** Pairing energy — two protons (or two neutrons) with opposite spins can occupy the same quantum state, lowering their combined energy. Even-even nuclei fully exploit this; odd-odd nuclei cannot.", "keywords": ["factor", "even", "odd", "configuration", "pairing", "dose", "isotope"], "source": "Part 1"}, {"heading": "Factor 3: Magic Numbers", "body": "Magic numbers for protons or neutrons: **2, 8, 20, 28, 50, 82, 126**\n\n- **Doubly magic nuclei** (both Z and N are magic) are exceptionally stable:\n  - ⁴He (Z=2, N=2)\n  - ¹⁶O (Z=8, N=8)\n  - ⁴⁰Ca (Z=20, N=20)\n  - ²⁰⁸Pb (Z=82, N=126)\n\n- **Why magic numbers work:** Nuclear shell model (Goeppert Mayer, 1949) — nucleons occupy discrete quantum energy levels in a nuclear potential. Filled shells = closed shells = exceptional stability, analogous to noble gases in chemistry.\n\n- **Evidence for magic numbers:**\n  - Tin (Z=50) has 10 stable isotopes — more than any other element.\n  - Nuclei with magic N have more stable isotones.\n  - Enhanced binding energy at magic numbers.\n  - SEMF underestimates binding at magic numbers (shell model needed).", "keywords": ["factor", "magic", "numbers", "binding energy", "semf", "shell model", "dose", "isotope"], "source": "Part 1"}, {"heading": "Factor 4: Binding Energy per Nucleon (BE/A)", "body": "- **Definition:** Energy required to separate a nucleus into individual nucleons, divided by A. Direct measure of stability per nucleon.\n- **BE/A curve:** Rises steeply for light nuclei → peaks at **⁵⁶Fe = 8.79 MeV/nucleon** → gradually falls for heavy nuclei.\n- **Key values:** ¹H ≈ 0 MeV/nucleon; ⁴He ≈ 7.07 MeV/nucleon; ⁵⁶Fe ≈ 8.79 MeV/nucleon; ²³⁸U ≈ 7.6 MeV/nucleon.\n- **Why fusion releases energy:** Light nuclei have low BE/A; fusing them produces a product with higher BE/A → greater total binding → mass decreases → energy released.\n- **Why fission releases energy:** Heavy nuclei (e.g., ²³⁵U, BE/A ≈ 7.6 MeV) split into medium-mass fragments with higher BE/A (~8.5 MeV) → energy released.\n- **Why ⁵⁶Fe can release energy from neither:** It sits at the top of the curve. Fusing it would produce a product with lower BE/A; splitting it would produce fragments with lower BE/A. Both require energy input.\n\n---", "keywords": ["factor", "binding", "energy", "per", "nucleon", "binding energy", "fission", "fusion", "dose"], "source": "Part 1"}, {"heading": "Term-by-term explanation", "body": "- **Volume term (+15.75·A):** Nuclear binding is short-range, so each nucleon only interacts with nearest neighbours. Binding is proportional to total nucleons A. Always positive — major contributor.\n- **Surface term (−17.8·A^(2/3)):** Surface nucleons have fewer neighbours → less binding. Proportional to nuclear surface area (~A^(2/3)). Always negative (correction).\n- **Coulomb term (−0.711·Z(Z−1)/A^(1/3)):** All Z protons repel each other; total repulsion scales as Z(Z−1) pairs divided by nuclear radius (~A^(1/3)). Always negative. Grows fast with Z.\n- **Asymmetry term (−23.7·(N−Z)²/A):** Pauli exclusion principle penalises nuclei where N ≠ Z — unequal numbers means some nucleons must occupy higher energy levels. Minimum (zero penalty) when N = Z. Larger for lighter nuclei (divided by A).\n- **Pairing term (±11.18/√A):** +δ for even-even, 0 for odd-A, −δ for odd-odd. Reflects quantum pairing of nucleons.", "keywords": ["term", "explanation", "activity", "strong force", "neutrino", "dose", "pairing", "nuclear radius"], "source": "Part 1"}, {"heading": "Worked Example: ⁵⁶Fe (Z=26, N=30, A=56)", "body": "| Term | Calculation | Value |\n|---|---|---|\n| Volume | 15.75 × 56 | +882.00 MeV |\n| Surface | −17.8 × 56^(2/3) = −17.8 × 15.02 | −267.36 MeV |\n| Coulomb | −0.711 × (26×25) / 56^(1/3) = −0.711 × 650 / 3.83 | −120.61 MeV |\n| Asymmetry | −23.7 × (30−26)² / 56 = −23.7 × 16/56 | −6.77 MeV |\n| Pairing | +11.18 / √56 = +11.18 / 7.48 (even-even → +δ) | +1.49 MeV |\n| **Total BE** | | **~489 MeV** |\n| **BE/A** | 489 / 56 | **~8.73 MeV/nucleon** |\n\nExperimental value: 8.79 MeV/nucleon. SEMF is within 1% (slight underestimate near magic numbers is expected).", "keywords": ["worked", "example", "⁵⁶fe", "binding energy", "semf", "shell model", "strong force", "pairing"], "source": "Part 1"}, {"heading": "Limitations of SEMF", "body": "- Underestimates binding near magic numbers — shell model effects not captured.\n- Does not predict individual excited states or nuclear spins.\n- Less accurate for very light nuclei (A < 10).\n\n---", "keywords": ["limitations", "semf", "activity", "shell model"], "source": "Part 1"}, {"heading": "Uranium-238 Decay Chain", "body": "The U-238 series: **14 steps** (8α + 6β⁻), ends at stable **Pb-206**.\n\n| Step | Parent → Daughter | Decay | Half-life |\n|---|---|---|---|\n| 1 | U-238 → Th-234 | α | 4.47 × 10⁹ y |\n| 2 | Th-234 → Pa-234 | β⁻ | 24.1 d |\n| 3 | Pa-234 → U-234 | β⁻ | 6.7 h |\n| 4 | U-234 → Th-230 | α | 2.45 × 10⁵ y |\n| 5 | Th-230 → Ra-226 | α | 7.54 × 10⁴ y |\n| 6 | Ra-226 → Rn-222 | α | 1600 y |\n| 7 | Rn-222 → Po-218 | α | 3.82 d |\n| 8 | Po-218 → Pb-214 | α | 3.05 min |\n| 9 | Pb-214 → Bi-214 | β⁻ | 26.8 min |\n| 10 | Bi-214 → Po-214 | β⁻ | 19.7 min |\n| 11 | Po-214 → Pb-210 | α | 164 μs |\n| 12 | Pb-210 → Bi-210 | β⁻ | 22.2 y |\n| 13 | Bi-210 → Po-210 | β⁻ | 5.01 d |\n| 14 | Po-210 → Pb-206 | α | 138 d → **STABLE** |", "keywords": ["uranium", "238", "decay", "chain", "beta decay", "half-life", "u-238"], "source": "Part 1"}, {"heading": "Why Alpha and Beta Alternate", "body": "- **Alpha decay** reduces Z by 2 — this often pushes the daughter below the valley (proton-poor → N/Z too high actually... wait, it reduces both N and Z by 2, which tends to shift toward the valley but can leave nuclei neutron-rich relative to valley).\n- **Beta-minus decay** then adjusts by converting a neutron to a proton, moving back toward N = Z line.\n- The alternation reflects the valley's curved shape: after each α decay, the daughter is often too neutron-rich and corrects with β⁻.", "keywords": ["alpha", "beta", "alternate", "alpha decay", "beta decay", "valley of stability", "radiation", "n/z"], "source": "Part 1"}, {"heading": "Secular Equilibrium", "body": "**Definition:** After a time much longer than the longest daughter half-life, every daughter's activity equals the parent's activity.\n\n**Condition:** t >> t½(daughter) for all daughters.\n\n**Equation:** A_daughter = A_parent when equilibrium is reached.\n\n**Practical consequence:** Radon-222 (t½ = 3.82 days) is continuously produced by Ra-226 (which is itself in the U-238 chain) in the ground. It seeps into buildings at a constant rate — this is why radon is a persistent indoor health hazard. The supply never runs out on human timescales because U-238's 4.47 Gy half-life means it decays at essentially a constant rate.\n\n---", "keywords": ["secular", "equilibrium", "half-life", "activity", "u-238", "dose"], "source": "Part 1"}, {"heading": "Core Equations", "body": "| Equation | Formula | Variables |\n|---|---|---|\n| Exponential decay | N(t) = N₀ e^(−λt) | N₀ = initial nuclei, λ = decay constant, t = time |\n| Half-life | t½ = 0.693 / λ | |\n| Activity | A = λN = (0.693/t½)·N | Bq = disintegrations per second |\n| Activity over time | A(t) = A₀ e^(−λt) | A₀ = initial activity |\n| Using half-lives directly | N(t) = N₀ × (½)^(t/t½) | Equivalent to above |\n| Age from ratio | t = (t½/ln2) × ln(N₀/N) | |", "keywords": ["core", "equations", "half-life", "activity"], "source": "Part 1"}, {"heading": "Units of Activity", "body": "| Unit | Definition | Relationship |\n|---|---|---|\n| Becquerel (Bq) | 1 disintegration per second | SI unit |\n| Curie (Ci) | Activity of 1 g of Ra-226 | 1 Ci = 3.70 × 10¹⁰ Bq |\n| MBq | Megabecquerel | 10⁶ Bq |\n| GBq | Gigabecquerel | 10⁹ Bq |", "keywords": ["units", "activity", "historical"], "source": "Part 1"}, {"heading": "Step-by-Step: Solving \"When does activity reach X?\" Problems", "body": "1. Write: A(t) = A₀ × (½)^(t/t½)\n2. Divide both sides by A₀: A/A₀ = (½)^(t/t½)\n3. Recognise the fraction as a power of ½: e.g., 100/800 = 1/8 = (½)³ → t/t½ = 3\n4. Solve for t: t = 3 × t½", "keywords": ["step", "solving", "activity", "reach", "problems", "half-life"], "source": "Part 1"}, {"heading": "Important Properties of Half-Life", "body": "- Intrinsic nuclear property — does NOT depend on temperature, pressure, chemical bonding, or sample history.\n- This distinguishes radioactive decay from all chemical processes.\n- Statistical law: applies to large samples; individual atoms decay randomly.", "keywords": ["important", "properties", "half", "life", "radioactive decay"], "source": "Part 1"}, {"heading": "Key Half-Lives and Applications", "body": "| Isotope | Half-life | Decay mode | Application |\n|---|---|---|---|\n| ¹⁴C | 5,730 years | β⁻ | Radiocarbon dating (up to ~50,000 y) |\n| ²³⁸U | 4.47 × 10⁹ years | α | Geological dating, nuclear fuel |\n| ²³⁵U | 7.04 × 10⁸ years | α | Nuclear reactor fuel (fissile) |\n| ⁶⁰Co | 5.27 years | β⁻ + γ | Cancer radiotherapy |\n| ⁹⁹ᵐTc | 6.0 hours | γ | Diagnostic nuclear medicine (~80% of scans) |\n| ¹³¹I | 8.0 days | β⁻ + γ | Thyroid diagnosis and treatment |\n| ¹⁸F | 110 minutes | β⁺ | PET scanning |\n| ²¹⁰Po | 138 days | α | Thermoelectric power (space probes) |\n| ²⁴¹Am | ~432 years | α | Smoke detectors |\n| ²¹²Po | 0.3 μs | α | Fastest alpha emitter in U/Th chains |\n| ²¹⁴Po | 164 μs | α | Step 11 of U-238 chain |\n\n---", "keywords": ["key", "half", "lives", "applications", "beta decay", "half-life", "activity", "u-238", "carbon-14", "pet", "reactor", "radiation", "isotope", "dating", "radioactive decay"], "source": "Part 1"}, {"heading": "Nuclear Medicine — Technetium-99m", "body": "- **Production:** Mo-99 decays by β⁻ to Tc-99m in hospital generators.\n  - ⁹⁹₄₂Mo → ⁹⁹ᵐ₄₃Tc + β⁻ + ν̄_e\n- **Why ideal:** 6-hour half-life (long enough for procedure, short enough to minimise dose); pure γ emitter (detectable outside body, no charged particle tissue damage); versatile chemistry (can be attached to many compounds).\n- **Isomeric transition:** Tc-99m is a metastable excited state. It decays to Tc-99 by gamma emission only.", "keywords": ["nuclear", "medicine", "technetium", "99m", "beta decay", "gamma", "half-life", "activity", "tc-99m", "radiation", "dose", "isotope"], "source": "Part 1"}, {"heading": "PET Scanning — Fluorine-18", "body": "- Patient injected with ¹⁸F-labelled glucose analog (FDG).\n- ¹⁸F undergoes β⁺ decay (t½ = 110 min).\n- Emitted positron travels a few mm, then annihilates with an electron.\n- Annihilation produces **two 511 keV gamma rays** in **opposite directions** (180° apart).\n- PET scanner detects coincident pairs → 3D metabolic map.\n- Cancers consume more glucose → appear as \"hot spots.\"", "keywords": ["pet", "scanning", "fluorine", "beta decay", "gamma", "half-life", "activity", "radiation"], "source": "Part 1"}, {"heading": "Radiocarbon Dating — Carbon-14", "body": "- ¹⁴C produced in upper atmosphere: cosmic ray neutrons hit ¹⁴N → ¹⁴C + p.\n- ¹⁴C incorporated into CO₂ → photosynthesis → food chains → all living organisms.\n- Ratio ¹⁴C/¹²C constant in living organisms (equilibrium with atmosphere).\n- At death: no new ¹⁴C ingested → ¹⁴C decreases with t½ = 5,730 y.\n- Measure current ¹⁴C activity, compare with expected initial activity → calculate age.\n- **Range:** Up to ~50,000 years (beyond this, ¹⁴C too depleted to measure accurately).\n- **Assumption:** Closed system (no external C since death); initial ¹⁴C/¹²C ratio known.", "keywords": ["radiocarbon", "dating", "carbon", "half-life", "activity"], "source": "Part 1"}, {"heading": "Uranium-Lead Dating", "body": "- Uses the ²³⁸U → ²⁰⁶Pb chain (t½ = 4.47 Gy).\n- Measures ratio of ²⁰⁶Pb to ²³⁸U in a mineral.\n- Each U-238 decay ultimately produces exactly one Pb-206 atom.\n- Age equation: t = (1/λ) × ln(1 + N_daughter/N_parent)\n- **Range:** Millions to billions of years — geological and cosmological timescales.\n- **Key assumption:** Closed system (no Pb entered or left the mineral since formation).", "keywords": ["uranium", "lead", "dating", "half-life", "u-238", "dose"], "source": "Part 1"}, {"heading": "Nuclear Reactors", "body": "- Use **induced fission** of ²³⁵U (not spontaneous).\n- U-235 (0.7% of natural uranium) is **fissile** — splits when hit by slow (thermal) neutrons.\n- U-238 absorbs neutrons without fissioning — acts as neutron \"poison\" → enrichment needed to 3–5% U-235.\n- Chain reaction: one fission releases 2–3 neutrons → sustain controlled chain reaction.\n- Provides ~10% of global electricity.", "keywords": ["nuclear", "reactors", "activity", "u-238", "fission", "reactor"], "source": "Part 1"}, {"heading": "Smoke Detectors — Americium-241", "body": "- Am-241 (α emitter, t½ ≈ 432 y) ionises air between two electrodes → small steady current.\n- Smoke particles absorb α particles → current drops → alarm triggers.\n- Safe: α particles cannot penetrate the plastic casing.\n\n---", "keywords": ["smoke", "detectors", "americium", "241", "half-life"], "source": "Part 1"}, {"heading": "Question 8.1", "body": "**A nucleus located above the valley of stability has an excess of neutrons. Which decay mode will most likely restore it toward stability?**\n\n**Answer: (b) β⁻ decay**\n\n**Explanation:**\nA nucleus above the valley of stability has too many neutrons relative to protons (N/Z is too high). Beta-minus decay converts a neutron into a proton:\n> n → p + e⁻ + ν̄_e\n\nThis increases Z by 1 and decreases N by 1, moving the nucleus diagonally toward the valley of stability. The mass number A remains unchanged.\n\n- (a) α decay would reduce both N and Z by 2 — for a light/medium nucleus this would not move it toward the valley.\n- (c) β⁺ decay converts a proton to a neutron, which would make the nucleus even more neutron-rich — the wrong direction.\n- (d) γ emission does not change N or Z at all.\n\n---", "keywords": ["question", "alpha decay", "beta decay", "valley of stability", "radiation", "n/z", "radioactive decay"], "source": "Part 1"}, {"heading": "Question 8.2", "body": "**Technetium-99m: t½ = 6.0 h, A₀ = 800 MBq. How many hours until A < 100 MBq?**\n\n**Answer: 18 hours**\n\n**Working:**\n\nUse A(t) = A₀ × (½)^(t/t½):\n\n100 = 800 × (½)^(t/6)\n\nDivide both sides by 800:\n> 100/800 = 1/8 = (½)^(t/6)\n\nRecognise that 1/8 = (½)³:\n> (½)³ = (½)^(t/6)\n\nTherefore: t/6 = 3 → **t = 18 hours**\n\n**Verification:** \n- After 6 h: 800 → 400 MBq\n- After 12 h: 400 → 200 MBq\n- After 18 h: 200 → 100 MBq ✓\n\n**Note:** After exactly 18 hours the activity equals exactly 100 MBq. For it to fall **below** 100, you need t > 18 hours. The answer is **18 hours** (or \"just over 18 hours\" if strict inequality is required).\n\n---", "keywords": ["question", "half-life", "activity", "tc-99m"], "source": "Part 1"}, {"heading": "Question 8.3", "body": "**Predict whether phosphorus-30 (Z=15, N=15) is stable. If radioactive, which decay mode?**\n\n**Answer: Radioactive; expected to undergo β⁺ decay**\n\n**Reasoning:**\n\n1. **N/Z ratio:** N/Z = 15/15 = 1.0. For Z = 15, the valley of stability sits slightly above N = Z — the stable phosphorus isotope is ³¹P (Z=15, N=16, N/Z ≈ 1.07). P-30 has one fewer neutron than the stable isotope, making it **proton-rich** (it sits **below** the valley of stability).\n\n2. **Even-odd configuration:** Z = 15 (odd), N = 15 (odd) → **odd-odd nucleus**. This is the least stable configuration, with only 4 stable odd-odd isotopes known across the entire chart of nuclides. P-30 is definitely not one of them.\n\n3. **Predicted decay mode:** Since P-30 is proton-rich (below the valley), it needs to convert a proton to a neutron. This means:\n   - **β⁺ decay** (if Q > 1.022 MeV): ³⁰P → ³⁰Si + e⁺ + ν_e\n   - Alternatively **electron capture** if the Q-value is below threshold.\n   - In practice, P-30 undergoes **β⁺ decay** (Q ≈ 4.23 MeV, well above threshold).\n\n4. **Conclusion:** P-30 is radioactive (not stable) due to both its proton-rich position below the valley AND its unfavourable odd-odd nucleon configuration. It undergoes β⁺ decay, increasing N by 1 and decreasing Z by 1 (becoming ³⁰Si), which is stable.\n\n---", "keywords": ["question", "beta decay", "valley of stability", "q-value", "isotope", "n/z", "pairing", "radioactive decay"], "source": "Part 1"}, {"heading": "Question 8.4", "body": "**Calculate the Q-value for alpha decay of Po-210 → Pb-206 + α**\n- Mass of Po-210: 209.9829 u\n- Mass of Pb-206: 205.9745 u\n- Mass of α (⁴He): 4.0026 u\n- 1 u = 931.5 MeV/c²\n\n**Answer: Q ≈ 5.40 MeV**\n\n**Working:**\n\nQ = (m_parent − m_daughter − m_alpha) × 931.5 MeV/u\n\nStep 1 — Mass difference:\n> Δm = 209.9829 − 205.9745 − 4.0026\n\n> Δm = 209.9829 − 209.9771\n\n> Δm = **0.0058 u**\n\nStep 2 — Convert to energy:\n> Q = 0.0058 × 931.5 = **5.40 MeV**\n\n**Interpretation:** This 5.40 MeV of energy is released as kinetic energy shared between the alpha particle and the recoiling Pb-206 nucleus. Since the alpha particle is much lighter, it carries away the majority of this energy.\n\n**Note:** The experimental value for Po-210 alpha decay is 5.30 MeV — the slight discrepancy is due to the mass values given in the question being rounded. Full working as shown is what earns marks.\n\n---", "keywords": ["question", "alpha decay", "radiation", "dose", "q-value"], "source": "Part 1"}, {"heading": "Question 8.5", "body": "**Why does Po-212 have t½ = 0.3 μs while U-238 has t½ = 4.47 billion years, despite both undergoing alpha decay?**\n\n**Full Answer:**\n\nBoth Po-212 and U-238 decay by the same quantum tunnelling mechanism described by the Geiger-Nuttall law. The enormous difference in half-lives (a factor of ~10²⁰) comes from the difference in decay energy (Q-value):\n\n- **Po-212:** Q_α = 8.95 MeV (high energy)\n- **U-238:** Q_α = 4.27 MeV (low energy)\n\n**Mechanism:** The alpha particle exists as a pre-formed cluster inside the nucleus, bouncing against the Coulomb potential barrier. Each time it strikes the barrier, it has a small probability of quantum tunnelling through it.\n\n**Why energy matters so much:**\n- A higher Q-value means the alpha particle has more energy.\n- Higher energy → the alpha particle approaches the top of the Coulomb barrier → the barrier is narrower and lower relative to the particle's energy → significantly higher tunnelling probability per collision.\n- A lower Q-value (U-238) means the alpha particle has much less energy relative to the barrier → the barrier is wider and taller relative to the particle → exponentially lower tunnelling probability.\n\n**The Geiger-Nuttall law** (log₁₀ T½ ∝ 1/√E) shows that tunnelling probability depends exponentially on √E. This exponential relationship means a factor of only ~2 difference in decay energy translates into **20 orders of magnitude** difference in half-life.\n\n**In summary:** Alpha decay in both nuclei is the same mechanism (quantum tunnelling), but the much higher decay energy of Po-212 gives it an enormously higher tunnelling probability per unit time, resulting in an essentially instantaneous decay compared to the geological timescale of U-238.\n\n---", "keywords": ["question", "alpha decay", "half-life", "activity", "strong force", "quantum tunnelling", "u-238", "radiation", "dose", "q-value"], "source": "Part 1"}, {"heading": "Question 8.6", "body": "**Use the SEMF to explain why ⁵⁶Fe is more stable than ⁵⁵Fe.**\n\n**Full Answer:**\n\nCompare the two:\n- ⁵⁶Fe: Z = 26, N = 30, A = 56 → **even-even** nucleus\n- ⁵⁵Fe: Z = 26, N = 29, A = 55 → **even-odd** nucleus\n\n**Key SEMF differences:**\n\n1. **Pairing term (most important factor):**\n   - ⁵⁶Fe (even-even): receives a **positive pairing term** of +δ = +11.18/√56 ≈ **+1.49 MeV**\n   - ⁵⁵Fe (even-odd): pairing term = **0** (no bonus, no penalty)\n   - ⁵⁶Fe gains ~1.49 MeV of extra binding energy that ⁵⁵Fe does not have.\n\n2. **Asymmetry term:**\n   - ⁵⁶Fe: −23.7 × (30−26)²/56 = −23.7 × 16/56 ≈ **−6.77 MeV**\n   - ⁵⁵Fe: −23.7 × (29−26)²/55 = −23.7 × 9/55 ≈ **−3.88 MeV**\n   - ⁵⁵Fe actually has a **smaller asymmetry penalty** (N−Z is only 3 vs. 4 for ⁵⁶Fe).\n   - The asymmetry term alone would favour ⁵⁵Fe by ~2.9 MeV.\n\n3. **Net effect:**\n   - The pairing bonus for ⁵⁶Fe (+1.49 MeV) partially offsets but does not explain the full story on its own.\n   - However, the volume term also contributes one extra nucleon's worth of binding energy to ⁵⁶Fe.\n   - More fundamentally, ⁵⁶Fe sits at the **peak of the BE/A curve** — it is optimised for all SEMF terms together, including proximity to N=28 (magic number) and the full even-even pairing benefit.\n\n4. **Physical interpretation:**\n   - The additional neutron in ⁵⁶Fe (N=30) can pair with the N=29 neutron in ⁵⁵Fe to complete a pair, gaining the pairing energy.\n   - This pairing reflects the quantum mechanical advantage of two nucleons sharing a quantum state with opposite spins.\n\n**Conclusion:** ⁵⁶Fe's greater stability over ⁵⁵Fe is primarily due to the even-even pairing bonus in the SEMF, combined with its position at the peak of the binding energy per nucleon curve.\n\n---", "keywords": ["question", "binding energy", "semf", "shell model", "dose", "pairing"], "source": "Part 1"}, {"heading": "Question 8.7", "body": "**A sample of C-14 has activity 320 Bq. Initial activity was 640 Bq. t½(¹⁴C) = 5730 years. How old is the sample?**\n\n**Answer: 5,730 years old**\n\n**Working:**\n\nUsing the activity ratio:\n> A/A₀ = (½)^(t/t½)\n\n> 320/640 = ½ = (½)^(t/5730)\n\n> (½)¹ = (½)^(t/5730)\n\n> t/5730 = 1\n\n> **t = 5,730 years**\n\n**Interpretation:** Exactly one half-life has elapsed since the organism died. Half of the original ¹⁴C has decayed. The sample is 5,730 years old.\n\n**Alternative working using logarithms:**\n> t = (t½/ln2) × ln(A₀/A) = (5730/0.693) × ln(640/320) = 8267 × ln(2) = 8267 × 0.693 = 5,730 years ✓\n\n---", "keywords": ["question", "half-life", "activity", "carbon-14"], "source": "Part 1"}, {"heading": "Question 8.8", "body": "**Explain why (a) fusion of light nuclei releases energy and (b) fission of heavy nuclei releases energy, using binding energy per nucleon.**\n\n**Answer:**\n\n**(a) Why fusion releases energy:**\n\nLight nuclei (e.g., hydrogen isotopes ²H and ³H) have **low binding energy per nucleon** — they sit on the steeply rising left-hand part of the BE/A curve. When two light nuclei fuse, the product (e.g., ⁴He) has a **higher BE/A** than the reactants.\n\nHigher BE/A means each nucleon is more tightly bound in the product than it was in the reactants. Since the total binding energy has increased, the total mass of the products is **less** than the total mass of the reactants (by E = mc²). This mass difference is released as energy (kinetic energy of products + radiation).\n\nExample: ²H (BE/A ≈ 1.11 MeV) + ³H (BE/A ≈ 2.83 MeV) → ⁴He (BE/A ≈ 7.07 MeV) + n, releasing ~17.6 MeV.\n\n**(b) Why fission releases energy:**\n\nVery heavy nuclei (e.g., ²³⁵U or ²³⁸U) have **lower BE/A** (~7.6 MeV/nucleon) than medium-mass nuclei near the peak (~8.5 MeV/nucleon for A ≈ 100–130). When a heavy nucleus splits into two medium-mass fragments, the fragments sit higher on the BE/A curve.\n\nThe fragments have greater total binding energy than the original heavy nucleus. Again, this means the products have less total mass, and the mass difference is released as energy — typically ~200 MeV per fission event, orders of magnitude more per reaction than any chemical process.\n\n**Unifying principle:** In both cases, the reaction moves nuclei toward the peak of the BE/A curve (⁵⁶Fe). Any process that moves nuclei toward this peak releases energy; any process moving away from it requires energy input.\n\n---", "keywords": ["question", "activity", "binding energy", "fission", "fusion", "radiation", "dose", "isotope", "exam"], "source": "Part 1"}, {"heading": "Question 8.9 — Data Interpretation", "body": "**(a) Most stable nucleus and BE/A value:**\n\n**⁵⁶Fe** (iron-56) with BE/A ≈ **8.79 MeV/nucleon**. This is the peak of the binding energy per nucleon curve. Iron-56 is the most stable nucleus in existence.\n\n**(b) Why fusion of hydrogen into helium releases energy:**\n\nHydrogen isotopes have very low BE/A (proton alone: ~0 MeV, deuterium ²H: ~1.11 MeV, tritium ³H: ~2.83 MeV). Helium-4 has BE/A ≈ 7.07 MeV/nucleon. Fusion moves the system up the left side of the BE/A curve to a significantly higher value. The increase in total binding energy corresponds to a decrease in total mass, with the mass difference (Δm × c²) released as energy.\n\n**(c) Estimated energy released per fission of A=240 nucleus into two A=120 fragments:**\n\nFrom the BE/A curve:\n- A = 240 (heavy nucleus like ²⁴⁰Pu): BE/A ≈ 7.6 MeV/nucleon\n- A = 120 (medium-mass fragment like ¹²⁰Sn): BE/A ≈ 8.5 MeV/nucleon\n\nTotal binding energy before fission:\n> 7.6 × 240 = 1,824 MeV\n\nTotal binding energy after fission (two fragments):\n> 8.5 × 120 × 2 = 2,040 MeV\n\nEnergy released:\n> 2,040 − 1,824 = **~216 MeV per fission event**\n\nThis is consistent with the ~200 MeV typically quoted for uranium fission. The difference from 200 MeV is because the fragments are not perfectly symmetric and some energy goes to neutrons.\n\n**(d) Why ⁵⁶Fe cannot release energy from either fusion or fission:**\n\n⁵⁶Fe sits at the **peak** of the BE/A curve. It already has the maximum possible binding energy per nucleon.\n\n- **Fusion of ⁵⁶Fe:** The product would have A > 56 and a **lower** BE/A → less total binding energy per nucleon → the products would have MORE mass than the reactants → energy must be **input**, not released.\n- **Fission of ⁵⁶Fe:** The fragments would have A < 56 and also **lower** BE/A (left side of curve) → same result: products have less total binding energy → fission would also require energy input.\n\n⁵⁶Fe is in the most energetically favourable state possible. It cannot \"fall\" to a more stable configuration, so neither nuclear reaction releases energy from it.\n\n---", "keywords": ["question", "data", "interpretation", "binding energy", "fission", "fusion", "dose", "isotope"], "source": "Part 1"}, {"heading": "A1: What is the strong nuclear force and why does it have a limited range?", "body": "The strong nuclear force is one of the four fundamental forces. It acts between all nucleon pairs (p-p, n-n, p-n) with equal strength (charge independence). Its range is ~1–3 fm because it is mediated by mesons (in the Yukawa model), which have significant mass — unlike photons (which mediate the infinite-range electromagnetic force). Below ~0.5 fm it becomes repulsive, creating a \"hard core\" that prevents nuclear collapse. Its range limitation is why Coulomb repulsion eventually dominates in heavy nuclei despite being intrinsically weaker at short range.", "keywords": ["strong", "nuclear", "force", "limited", "range", "strong force", "forces"], "source": "Part 1"}, {"heading": "A2: Why does the N/Z ratio need to increase for heavier elements?", "body": "As Z increases, the Coulomb repulsion between protons grows as Z(Z−1) — roughly quadrupling each time Z doubles. The strong force is short-range and saturates (each nucleon only interacts with its nearest neighbours). Adding extra neutrons increases strong-force binding without increasing Coulomb repulsion, partially counteracting the growing electrostatic repulsion. However, beyond Pb-208 (Z=82), no neutron addition can compensate for the Coulomb repulsion, and all isotopes are radioactive.", "keywords": ["ratio", "need", "increase", "heavier", "elements", "strong force", "isotope", "forces"], "source": "Part 1"}, {"heading": "A3: What is the neutrino and why was it postulated?", "body": "Wolfgang Pauli postulated the neutrino in 1930 to explain the continuous beta decay energy spectrum. If beta decay were simply n → p + e⁻, then by conservation of energy and momentum, the electron would always be emitted with the same discrete energy (like alpha particles). Experimentally, the electrons show a continuous spectrum from near-zero to a maximum Q-value. Pauli proposed a third, undetected particle (the neutrino/antineutrino) that carries away the remaining energy and momentum, restoring conservation laws. The neutrino was directly detected in 1956 by Reines and Cowan.", "keywords": ["neutrino", "postulated", "alpha decay", "beta decay", "radiation", "dose", "q-value", "conservation"], "source": "Part 1"}, {"heading": "A4: What is parity violation and who discovered it experimentally?", "body": "Parity is mirror symmetry — a law is parity-conserving if it behaves identically in a mirror image. In 1956, Lee and Yang theorised the weak force might violate parity. Chien-Shiung Wu confirmed this by aligning cobalt-60 nuclei at near-absolute zero temperatures and showing beta particles are emitted preferentially in one direction — an asymmetry that cannot exist if mirror symmetry holds. This was one of the most profound discoveries in 20th-century physics, proving the weak force does not respect left-right symmetry.", "keywords": ["parity", "violation", "who", "discovered", "experimentally", "radiation"], "source": "Part 1"}, {"heading": "A5: How do we know that half-life is independent of external conditions?", "body": "Multiple lines of evidence confirm this. Radioactive samples measured in high-pressure environments, extremely hot or cold conditions, different chemical compounds, and different gravitational fields all yield identical half-lives within measurement precision. This is because radioactive decay involves nuclear energy scales (~MeV) that are millions of times larger than chemical energies (~eV) or any thermodynamic energy available in a laboratory or even stellar environment (except in stellar cores). The nuclear wave function is effectively unaffected by chemical bonding or thermal motion.", "keywords": ["know", "half", "life", "independent", "external", "conditions", "activity", "dose", "radioactive decay"], "source": "Part 1"}, {"heading": "A6: What is a doubly magic nucleus and why is it so stable?", "body": "A doubly magic nucleus has both Z and N equal to magic numbers. Examples: ⁴He (2,2), ¹⁶O (8,8), ⁴⁰Ca (20,20), ²⁰⁸Pb (82,126). In the nuclear shell model, magic numbers correspond to completely filled nuclear shells. When both proton and neutron shells are full, the nucleus has a particularly low energy state (high binding energy), large excitation energies to the first excited state, and high resistance to deformation. The analogy to noble gases (completely filled electron shells) in chemistry is precise — both represent exceptional stability from shell closure.", "keywords": ["doubly", "magic", "nucleus", "stable", "activity", "binding energy", "shell model", "dose", "exam"], "source": "Part 1"}, {"heading": "A7: Why does tin have 10 stable isotopes — more than any other element?", "body": "Tin has Z = 50, which is a magic proton number. A magic proton number means the proton shell is completely filled, giving the nucleus exceptional stability for a wide range of neutron numbers. The proton contribution to stability is maximised, allowing many different neutron numbers (N = 62 to 74) to produce stable isotopes. By comparison, tin's neighbours indium (Z=49) and antimony (Z=51) have only two stable isotopes each — no magic numbers to provide the extra stability.", "keywords": ["tin", "stable", "isotopes", "any", "element", "shell model", "isotope"], "source": "Part 1"}, {"heading": "A8: What is the difference between activity and dose?", "body": "- **Activity** measures the rate of radioactive disintegrations (Bq or Ci) — it tells us how many nuclear decays occur per second.\n- **Dose** measures the energy deposited in tissue by radiation. The absorbed dose is measured in Gray (Gy) = 1 J/kg. Effective dose (Sievert, Sv) also accounts for radiation type and tissue sensitivity.\n- A highly active source is not necessarily more dangerous than a less active one if it emits less penetrating radiation (e.g., alpha emitters are very dangerous if inhaled but safe outside the body).", "keywords": ["difference", "activity", "dose", "radiation"], "source": "Part 1"}, {"heading": "A9: What is the difference between U-235 and U-238 regarding nuclear reactors?", "body": "- **U-235 (0.7% of natural uranium):** Fissile — absorbs a slow (thermal) neutron and undergoes induced fission, releasing ~200 MeV and 2–3 more neutrons to sustain a chain reaction.\n- **U-238 (99.3% of natural uranium):** Not fissile — absorbs neutrons without fissioning (resonance absorption). Acts as a neutron \"poison\" that would stop a chain reaction if concentrated.\n- Natural uranium must be enriched to 3–5% U-235 for most reactor designs. Weapons-grade uranium is >90% U-235.\n- U-238 can absorb a neutron and convert to Pu-239 (plutonium), which is fissile — this is how breeder reactors work.", "keywords": ["difference", "235", "238", "regarding", "nuclear", "reactors", "u-238", "fission", "reactor"], "source": "Part 1"}, {"heading": "A10: How does quantum tunnelling enable alpha decay?", "body": "Classically, an alpha particle inside the nucleus faces a Coulomb potential barrier: the region just outside the nucleus where electrostatic repulsion from the protons would need to be overcome. The alpha particle's kinetic energy (4–9 MeV) is less than the peak of this Coulomb barrier (~30 MeV for heavy nuclei), so classically it could never escape.\n\nQuantum mechanically, particles have wave-like properties and a non-zero probability of being found in classically forbidden regions. The alpha particle's wavefunction extends through the barrier. With each bounce against the nuclear surface (at ~10²¹ times per second), there is a tiny probability of tunnelling through the barrier. The probability depends exponentially on the barrier width and height relative to the particle's energy — which is why the Geiger-Nuttall law shows such extreme sensitivity of half-life to decay energy.", "keywords": ["a10", "quantum", "tunnelling", "enable", "alpha", "decay", "alpha decay", "half-life", "strong force", "quantum tunnelling", "radiation", "dose"], "source": "Part 1"}, {"heading": "A11: Why is radon a health hazard in homes?", "body": "Radon-222 is a radioactive noble gas (t½ = 3.82 d, alpha emitter) produced in the U-238 decay chain from radium-226. Because uranium is naturally present in soil and rock, Ra-226 is constantly present, and its decay continuously produces Rn-222. As a noble gas, radon doesn't bind chemically — it seeps upward through soil and can accumulate in poorly ventilated basements and ground-floor rooms. When inhaled, radon and its short-lived alpha-emitting daughters (Po-218, Pb-214, Bi-214, Po-214) can deposit in lung tissue and deliver damaging alpha radiation directly to lung cells. Radon is the second leading cause of lung cancer after smoking.", "keywords": ["a11", "radon", "health", "hazard", "homes", "half-life", "u-238", "radiation"], "source": "Part 1"}, {"heading": "A12: What is the difference between spontaneous and induced fission?", "body": "- **Spontaneous fission:** The nucleus splits on its own, without any trigger. Significant only for Z ≥ 100 (e.g., californium-252). Competes with alpha decay. Not used in nuclear power.\n- **Induced fission:** A fissile nucleus (e.g., U-235) absorbs a neutron, becomes briefly highly excited (compound nucleus U-236*), and then splits into two fission fragments plus typically 2–3 neutrons. This is the basis of nuclear reactors and nuclear weapons.\n- The neutrons released can trigger further fissions → chain reaction. In reactors, control rods (boron/cadmium) absorb excess neutrons to maintain a controlled, sustained reaction. In weapons, a supercritical mass is assembled rapidly to allow exponential growth.", "keywords": ["a12", "difference", "spontaneous", "induced", "fission", "alpha decay", "activity", "pet", "reactor", "radiation"], "source": "Part 1"}, {"heading": "A13: What conservation laws govern nuclear decay?", "body": "All nuclear decays must conserve:\n1. **Mass-energy** (E = mc²; mass defect appears as kinetic energy of products)\n2. **Linear momentum** (products recoil)\n3. **Angular momentum** (nuclear spins conserved overall)\n4. **Electric charge** (Z, adjusted for emitted particles)\n5. **Baryon number** (total number of nucleons conserved)\n6. **Lepton number** (electrons, positrons, neutrinos counted with appropriate signs)\n7. **Mass number A** (in α, β, γ — NOT in fission)", "keywords": ["a13", "conservation", "laws", "govern", "nuclear", "decay", "binding energy", "neutrino", "fission", "dose"], "source": "Part 1"}, {"heading": "A14: What is an isomer? Give an example.", "body": "A nuclear isomer is a metastable excited state of a nucleus — it has the same Z and N as the ground state but exists in a higher energy configuration that is relatively long-lived (half-life > 1 ns, as opposed to typical excited states that decay in 10⁻¹² s). The \"m\" in Tc-99m denotes \"metastable.\" Tc-99m (t½ = 6.0 h) decays to Tc-99 by emitting a 140 keV gamma ray. This energy is ideal for nuclear medicine: energetic enough to escape the body and be detected, but not so energetic as to require impractically thick shielding.\n\n---", "keywords": ["a14", "isomer", "give", "example", "gamma", "half-life", "activity", "tc-99m", "radiation", "dose", "isotope", "applications"], "source": "Part 1"}, {"heading": "12. COMMON MISCONCEPTIONS — CORRECTED", "body": "## 12. COMMON MISCONCEPTIONS — CORRECTED\n\n| Misconception | Correction |\n|---|---|\n| \"All radiation is equally dangerous\" | Alpha, beta, and gamma have very different penetrating powers. Alpha particles are stopped by paper and skin; gamma rays require lead/concrete shielding. Danger depends on radiation type, dose rate, exposure time, and whether the source is inside or outside the body. |\n| \"Half-life means exactly half the atoms decay at t½\" | Half-life is a statistical average for large samples. Individual atoms decay randomly at any time. For small samples, statistical fluctuations become significant. |\n| \"Neutrons don't matter because they have no charge\" | Neutrons are essential for nuclear stability. They provide strong-force binding without adding Coulomb repulsion. Without neutrons, no nucleus heavier than ¹H could exist. |\n| \"Radioactive decay produces dangerous products forever\" | Most nuclear waste decays to safe levels within years to centuries. Only a small fraction (transuranic elements, long-lived isotopes like Tc-99) remains hazardous for long periods. The activity of any sample continuously decreases. |\n| \"Radioactive decay can be slowed by cooling or changing chemistry\" | Half-life is entirely independent of temperature, pressure, and chemical environment. Nuclear energy scales (MeV) are millions of times larger than chemical/thermal energies (eV). |\n| \"Half-life is when all atoms have decayed by half\" | After one half-life, half the atoms remain (not: half have decayed and stopped). After two half-lives, one-quarter remain; after ten half-lives, 1/1024 ≈ 0.1% remain. |\n| \"The valley of stability means those isotopes are unchanging\" | Some valley-of-stability isotopes are only very slightly stable or are stable on such long timescales (e.g., ²⁰⁹Bi, t½ ≈ 2 × 10¹⁹ years via alpha decay) that they are effectively stable for all practical purposes but technically decay. |\n| \"Alpha particles are harmless because they're stopped by skin\" | Alpha emitters are dangerous if inhaled or ingested (e.g., radon daughters in the lung, polonium-210 in food/drink). Inside the body, alpha particles deposit all their energy in a small volume of tissue, causing severe localised damage. |\n| \"Fusion is always better than fission\" | Fusion produces less long-lived radioactive waste and uses abundant fuel (hydrogen isotopes), but requires temperatures of ~100 million °C that have not yet been sustained in a net-energy-producing reactor on Earth. Both have advantages and challenges. |\n| \"Beta decay violates conservation of energy\" | Beta decay only appears to violate energy conservation if the neutrino is ignored. Including the antineutrino/neutrino restores conservation of energy, momentum, and lepton number simultaneously. This was Pauli's 1930 insight. |\n\n---", "keywords": ["common", "misconceptions", "corrected", "alpha decay", "beta decay", "gamma", "half-life", "activity", "valley of stability", "strong force", "neutrino", "fission", "fusion", "reactor", "radiation", "dose", "isotope", "conservation", "exam", "radioactive decay", "forces"], "source": "Part 1"}, {"heading": "Fundamental Constants (for calculations)", "body": "| Constant | Value |\n|---|---|\n| 1 atomic mass unit (u) | 931.5 MeV/c² |\n| Mass of proton | 1.007276 u = 938.3 MeV/c² |\n| Mass of neutron | 1.008665 u = 939.6 MeV/c² |\n| Mass of alpha particle | 4.001507 u |\n| Mass of electron/positron | 0.000549 u = 0.511 MeV/c² |\n| ln(2) | 0.6931 |\n| 1 femtometre (fm) | 10⁻¹⁵ m |\n| 1 Curie (Ci) | 3.70 × 10¹⁰ Bq |", "keywords": ["fundamental", "constants", "calculations", "alpha decay", "activity", "radiation", "historical"], "source": "Part 1"}, {"heading": "Magic Numbers Summary", "body": "| Magic number | Element(s) with that many protons | Notes |\n|---|---|---|\n| 2 | Helium | ⁴He doubly magic |\n| 8 | Oxygen | ¹⁶O doubly magic |\n| 20 | Calcium | ⁴⁰Ca doubly magic |\n| 28 | Nickel | ⁵⁶Fe near N=28 |\n| 50 | Tin | Most stable isotopes (10) |\n| 82 | Lead | ²⁰⁸Pb doubly magic (N=126) |\n| 126 | (neutron-only) | N=126 in ²⁰⁸Pb |", "keywords": ["magic", "numbers", "summary", "activity", "shell model", "isotope"], "source": "Part 1"}, {"heading": "Decay Mode Quick Predictor", "body": "| Situation | Most likely decay |\n|---|---|\n| N/Z too high (above valley) | β⁻ decay |\n| N/Z too low (below valley), Q > 1.022 MeV | β⁺ decay |\n| N/Z too low (below valley), Q < 1.022 MeV | Electron capture |\n| Z > 83, A > 210 | α decay |\n| Excited state (same Z and N as ground state) | γ emission |\n| Z ≥ 100 | Spontaneous fission (competes with α) |\n| Odd-odd nucleus | Likely unstable (only 4 stable odd-odd nuclides exist) |\n| Doubly magic nucleus | Exceptionally stable |", "keywords": ["decay", "mode", "quick", "predictor", "alpha decay", "beta decay", "activity", "valley of stability", "pet", "fission", "n/z", "pairing"], "source": "Part 1"}, {"heading": "How to Calculate Any Half-Life / Activity / Age Problem", "body": "| Unknown | Given | Formula |\n|---|---|---|\n| N at time t | N₀, λ or t½ | N = N₀ × (½)^(t/t½) |\n| A at time t | A₀, t½ | A = A₀ × (½)^(t/t½) |\n| Time to reach N or A | N₀ or A₀, t½ | t = t½ × log₂(N₀/N) = t½ × n half-lives |\n| Age of sample (dating) | A₀, A, t½ | t = (t½ / ln2) × ln(A₀/A) |\n| Age (parent-daughter ratio) | N_daughter, N_parent, λ | t = (1/λ) × ln(1 + N_d/N_p) |\n| λ from t½ | t½ | λ = 0.693 / t½ |\n| t½ from λ | λ | t½ = 0.693 / λ |", "keywords": ["calculate", "any", "half", "life", "activity", "age", "problem", "half-life", "dating"], "source": "Part 1"}, {"heading": "Forces Comparison", "body": "| Property | Strong Nuclear Force | Electromagnetic Force |\n|---|---|---|\n| Relative strength at 1 fm | ~100× stronger than EM | Reference |\n| Range | ~1–3 fm | Infinite (1/r²) |\n| Acts on | All nucleons (charge independent) | Charged particles only |\n| Below 0.5 fm | Repulsive (hard core) | Still attractive/repulsive |\n| Governs stability in light nuclei | Dominant | Minor |\n| Governs stability in heavy nuclei | Limited by short range | Increasingly dominant (Z(Z−1) scaling) |\n\n---\n\n*End of Chapter 8 AI Reference Document*", "keywords": ["forces", "comparison", "strong force"], "source": "Part 1"}, {"heading": "AI Reference Document — Part 2: Complete Supplementary Coverage", "body": "## AI Reference Document — Part 2: Complete Supplementary Coverage\n\n> **Use this alongside Part 1.** This document fills every gap: complete glossary, every historical figure, nuclear notation, nuclear radius, radiation penetration, dose units, all three natural decay series, specific activity, transient equilibrium, expanded worked examples, and every additional question type a student could possibly ask.\n\n---", "keywords": ["reference", "document", "part", "complete", "supplementary", "coverage", "activity", "radiation", "dose", "secular equilibrium", "nuclear radius", "exam"], "source": "Part 2"}, {"heading": "Standard Nuclear Notation", "body": "> ᴬ_Z X  or  X-A\n\nWhere:\n- **X** = chemical symbol of the element\n- **A** = mass number (total nucleons = protons + neutrons)\n- **Z** = atomic number (number of protons) — determines which element it is\n- **N** = neutron number = A − Z (not always written explicitly)", "keywords": ["standard", "nuclear", "notation", "activity"], "source": "Part 2"}, {"heading": "Examples", "body": "| Notation | Element | Z | A | N |\n|---|---|---|---|---|\n| ¹²₆C or C-12 | Carbon | 6 | 12 | 6 |\n| ²³⁸₉₂U or U-238 | Uranium | 92 | 238 | 146 |\n| ⁵⁶₂₆Fe or Fe-56 | Iron | 26 | 56 | 30 |\n| ⁹⁹ᵐ₄₃Tc | Technetium (metastable) | 43 | 99 | 56 |\n| ⁴₂He | Helium / Alpha particle | 2 | 4 | 2 |", "keywords": ["examples", "alpha decay", "u-238", "tc-99m", "radiation"], "source": "Part 2"}, {"heading": "Nuclear Notation in Decay Equations", "body": "**Alpha decay:**\n> ²³⁸₉₂U → ²³⁴₉₀Th + ⁴₂He\n\nCheck: Left: A=238, Z=92. Right: A=234+4=238 ✓, Z=90+2=92 ✓\n\n**Beta-minus decay:**\n> ¹⁴₆C → ¹⁴₇N + ⁰₋₁e + ν̄_e\n\nThe electron is written as ⁰₋₁e (mass number 0, charge −1). Check: A=14 ✓, Z=6=7+(−1) ✓\n\n**Beta-plus decay:**\n> ¹⁸₉F → ¹⁸₈O + ⁰₊₁e + ν_e\n\nThe positron is written as ⁰₊₁e (mass number 0, charge +1).\n\n**Electron capture:**\n> ⁴⁰₁₉K + ⁰₋₁e → ⁴⁰₁₈Ar + ν_e\n\n**Gamma emission:**\n> ⁹⁹ᵐ₄₃Tc → ⁹⁹₄₃Tc + γ  (same Z and A, just loses energy)", "keywords": ["nuclear", "notation", "decay", "equations", "alpha decay", "beta decay", "gamma", "radiation", "dose"], "source": "Part 2"}, {"heading": "How to find the daughter nucleus", "body": "Given parent ᴬ_Z X and decay mode:\n- **α decay:** daughter is ᴬ⁻⁴_(Z−2) Y → subtract 4 from A, subtract 2 from Z\n- **β⁻ decay:** daughter is ᴬ_(Z+1) Y → A unchanged, add 1 to Z\n- **β⁺ decay:** daughter is ᴬ_(Z−1) Y → A unchanged, subtract 1 from Z\n- **EC:** daughter is ᴬ_(Z−1) Y → same as β⁺\n- **γ emission:** daughter is ᴬ_Z Y → nothing changes, only energy lost\n\n---", "keywords": ["find", "daughter", "nucleus", "alpha decay", "beta decay", "dose", "radioactive decay"], "source": "Part 2"}, {"heading": "Definitions", "body": "| Term | Definition | Example |\n|---|---|---|\n| **Nuclide** | A specific nucleus characterised by unique Z and N values | U-238 (Z=92, N=146) is one nuclide |\n| **Isotopes** | Nuclides with the same Z but different N (same element, different mass) | ¹²C, ¹³C, ¹⁴C — all carbon (Z=6) |\n| **Isobars** | Nuclides with the same A but different Z | ¹⁴C and ¹⁴N (both A=14, different elements) |\n| **Isotones** | Nuclides with the same N but different Z | ¹⁴C (N=8) and ¹⁶O (N=8) |\n| **Isomers (nuclear)** | Same Z and N but different energy states (one is metastable) | Tc-99 and Tc-99m (both Z=43, N=56) |\n| **Stable nuclide** | Does not spontaneously decay on any observable timescale | ¹²C, ¹⁶O, ²⁰⁸Pb |\n| **Radionuclide** | A nuclide that undergoes radioactive decay | U-238, C-14, Co-60 |\n| **Parent nucleus** | The original nucleus before decay | U-238 in the U-238 chain |\n| **Daughter nucleus** | The nucleus produced after decay | Th-234 after U-238 alpha decays |\n| **Nucleon** | Generic term for proton or neutron | ⁵⁶Fe has 56 nucleons |", "keywords": ["definitions", "alpha decay", "activity", "u-238", "carbon-14", "tc-99m", "radiation", "dose", "isotope", "exam", "radioactive decay"], "source": "Part 2"}, {"heading": "Why \"isotope\" is often used loosely", "body": "In everyday language, \"isotope\" is used to refer to any nuclide (e.g., \"radioactive isotopes\"). Technically, isotopes are variants of the same element. The more precise term for any specific nuclear species is \"nuclide.\" This distinction is rarely penalised in introductory courses but worth knowing.\n\n---", "keywords": ["isotope", "often", "used", "loosely", "activity"], "source": "Part 2"}, {"heading": "3. THE FOUR FUNDAMENTAL FORCES IN CONTEXT", "body": "## 3. THE FOUR FUNDAMENTAL FORCES IN CONTEXT\n\n| Force | Relative strength at 1 fm | Range | Mediator | Role in nucleus |\n|---|---|---|---|---|\n| **Strong nuclear** | 1 (reference) | ~1–3 fm | Gluons (residual: pions/mesons) | Binds nucleons together |\n| **Electromagnetic** | ~1/137 | Infinite (1/r²) | Photons | Repels protons; destabilises heavy nuclei |\n| **Weak nuclear** | ~10⁻⁶ | ~0.001 fm | W⁺, W⁻, Z bosons | Mediates β decay; converts n↔p |\n| **Gravity** | ~10⁻³⁸ | Infinite (1/r²) | Gravitons (theoretical) | Negligible at nuclear scales |", "keywords": ["four", "fundamental", "forces", "context"], "source": "Part 2"}, {"heading": "Key points for exam questions:", "body": "- The **strong force** is mediated by gluons between quarks; at the nucleon level it is mediated by residual exchange of pions/mesons (Yukawa potential). The textbook uses \"strong nuclear force\" to mean this residual strong force between nucleons.\n- The **weak force** is responsible for all beta decays. It is the only force that can change quark flavour (up quark ↔ down quark), which is what converts protons to neutrons and vice versa.\n- **Gravity** is so weak at nuclear scales that it has no measurable effect on nuclear stability.\n- Only the strong and weak forces operate purely at nuclear scales. Electromagnetism bridges nuclear and atomic scales.\n\n---", "keywords": ["key", "points", "exam", "questions", "beta decay", "strong force", "radiation", "forces"], "source": "Part 2"}, {"heading": "Nuclear Radius Formula", "body": "> R = R₀ × A^(1/3)\n\nWhere:\n- R = nuclear radius\n- R₀ = 1.2–1.3 fm (empirical constant, often given as 1.2 fm)\n- A = mass number\n\nThis formula reflects the fact that nucleons are nearly incompressible and pack at constant density — so volume ∝ A, and since volume ∝ R³, we get R ∝ A^(1/3).", "keywords": ["nuclear", "radius", "formula", "nuclear radius"], "source": "Part 2"}, {"heading": "Examples", "body": "| Nucleus | A | Radius R = 1.2 × A^(1/3) fm |\n|---|---|---|\n| ⁴He | 4 | 1.2 × 1.587 = 1.90 fm |\n| ¹²C | 12 | 1.2 × 2.289 = 2.75 fm |\n| ⁵⁶Fe | 56 | 1.2 × 3.826 = 4.59 fm |\n| ²³⁸U | 238 | 1.2 × 6.204 = 7.44 fm |", "keywords": ["examples"], "source": "Part 2"}, {"heading": "Nuclear Density", "body": "Since mass ∝ A (in atomic mass units) and volume ∝ R³ ∝ A:\n\n> Nuclear density ≈ constant ≈ **2.3 × 10¹⁷ kg/m³**\n\nThis is roughly 10¹⁴ times denser than water. A teaspoon (~5 cm³) of nuclear matter would weigh about 10⁸ tonnes.\n\nThis constant density is why the volume term in the SEMF (binding energy ∝ A) works — the nuclear interior has uniform density regardless of A.", "keywords": ["nuclear", "density", "binding energy", "semf", "dose", "nuclear radius"], "source": "Part 2"}, {"heading": "Why R ∝ A^(1/3) appears in the SEMF Coulomb term", "body": "The Coulomb energy between all Z(Z−1)/2 proton pairs separated by a distance of order R gives:\n> E_Coulomb ∝ Z(Z−1)/R ∝ Z(Z−1)/A^(1/3)\n\nThis is exactly the form of the Coulomb term in the SEMF.\n\n---", "keywords": ["appears", "semf", "coulomb", "term", "strong force", "dose"], "source": "Part 2"}, {"heading": "What is mass defect?", "body": "The actual mass of a nucleus is always **less** than the sum of the masses of its constituent protons and neutrons. This difference is the **mass defect** (Δm).\n\n> Δm = Z·m_p + N·m_n − m_nucleus\n\nThe missing mass has been converted to binding energy:\n> BE = Δm × c² = Δm × 931.5 MeV/u", "keywords": ["mass", "defect", "binding energy", "dose"], "source": "Part 2"}, {"heading": "Full Worked Example: Binding energy of ⁴He", "body": "Given:\n- m_p = 1.007276 u\n- m_n = 1.008665 u\n- m(⁴He nucleus) = 4.001507 u\n- ⁴He: Z=2, N=2\n\nStep 1 — Sum of separated nucleons:\n> 2 × 1.007276 + 2 × 1.008665 = 2.014552 + 2.017330 = 4.031882 u\n\nStep 2 — Mass defect:\n> Δm = 4.031882 − 4.001507 = 0.030375 u\n\nStep 3 — Binding energy:\n> BE = 0.030375 × 931.5 = 28.30 MeV\n\nStep 4 — BE/A:\n> BE/A = 28.30 / 4 = **7.07 MeV/nucleon**", "keywords": ["full", "worked", "example", "binding", "energy", "⁴he", "binding energy", "dose"], "source": "Part 2"}, {"heading": "Note on atomic vs nuclear masses", "body": "Textbooks often use **atomic masses** (which include electron masses) rather than nuclear masses. When using atomic masses:\n- The Z electron masses in the parent and daughter largely cancel in decay Q-value calculations.\n- For beta-plus decay, you must subtract 2×m_e (two electron masses = 1.022 MeV) because a positron is created (not just a proton, which would include an electron in the atomic mass).\n- This is why β⁺ decay requires Q > 1.022 MeV — the extra energy goes to create the positron's mass.\n\n---", "keywords": ["note", "atomic", "nuclear", "masses", "beta decay", "radiation", "dose", "q-value"], "source": "Part 2"}, {"heading": "What is specific activity?", "body": "Specific activity is the activity per unit mass of a radionuclide. It answers: \"How many decays per second does 1 gram of this isotope produce?\"", "keywords": ["specific", "activity", "isotope"], "source": "Part 2"}, {"heading": "Formula derivation", "body": "Number of nuclei in mass m (grams):\n> N = (m / M) × N_A\n\nWhere M = molar mass (g/mol) ≈ A (mass number) for most purposes, and N_A = 6.022 × 10²³ mol⁻¹ (Avogadro's number).\n\nActivity:\n> A = λN = (0.693 / t½) × (m × N_A / M)\n\nSpecific activity (per gram, m = 1):\n> A_specific = (0.693 × N_A) / (t½ × M)\n\nUnits: Bq/g (if t½ in seconds, M in g/mol)", "keywords": ["formula", "derivation", "half-life", "activity"], "source": "Part 2"}, {"heading": "Key insight: short half-life = high specific activity", "body": "A sample of ¹⁴C (t½ = 5730 years) has much lower activity per gram than ¹³¹I (t½ = 8 days) because each ¹³¹I atom decays much faster.", "keywords": ["key", "insight", "short", "half", "life", "high", "specific", "activity", "half-life"], "source": "Part 2"}, {"heading": "Worked Example: Activity of 1 μg of Tc-99m", "body": "- t½ = 6.0 hours = 6 × 3600 = 21,600 s\n- M = 99 g/mol\n- m = 1 × 10⁻⁶ g\n- N_A = 6.022 × 10²³ mol⁻¹\n\nStep 1 — Number of nuclei:\n> N = (1×10⁻⁶ / 99) × 6.022×10²³ = 6.082×10¹⁵ nuclei\n\nStep 2 — Decay constant:\n> λ = 0.693 / 21,600 = 3.208×10⁻⁵ s⁻¹\n\nStep 3 — Activity:\n> A = λN = 3.208×10⁻⁵ × 6.082×10¹⁵ = **1.95×10¹¹ Bq ≈ 195 GBq**\n\nThis explains why medical doses of Tc-99m are measured in hundreds of MBq yet involve only nanograms of material.", "keywords": ["worked", "example", "activity", "99m", "half-life", "tc-99m", "dose"], "source": "Part 2"}, {"heading": "Worked Example: Activity of 1 kg of U-238", "body": "- t½ = 4.47×10⁹ years = 4.47×10⁹ × 3.156×10⁷ s = 1.411×10¹⁷ s\n- M = 238 g/mol\n- m = 1000 g\n\n> N = (1000/238) × 6.022×10²³ = 2.530×10²⁴ nuclei\n\n> λ = 0.693 / 1.411×10¹⁷ = 4.91×10⁻¹⁸ s⁻¹\n\n> A = 4.91×10⁻¹⁸ × 2.530×10²⁴ = **1.24×10⁷ Bq = 12.4 MBq/kg**\n\nDespite being 1 kg of uranium, the activity is modest due to the enormous half-life. This is why natural uranium ore is only mildly radioactive.\n\n---", "keywords": ["worked", "example", "activity", "238", "half-life"], "source": "Part 2"}, {"heading": "Penetration Summary Table", "body": "| Radiation | Identity | Charge | Typical energy | Penetration in air | Stopped by |\n|---|---|---|---|---|---|\n| **Alpha (α)** | ⁴He nucleus | +2 | 4–9 MeV | ~3–10 cm | Paper, skin (0.07 mm dead skin layer) |\n| **Beta-minus (β⁻)** | Electron | −1 | 0 to Q_max (variable) | ~1–3 m | Plastic, glass, few mm aluminium |\n| **Beta-plus (β⁺)** | Positron | +1 | 0 to Q_max | ~1–3 m | Plastic, glass; annihilates → produces 511 keV gamma |\n| **Gamma (γ)** | Photon | 0 | keV–MeV | Hundreds of metres | Lead, concrete, thick water (no complete stop, only attenuated) |\n| **Neutron** | Neutron | 0 | keV–MeV | Very penetrating | Water, polyethylene (hydrogen-rich materials moderate neutrons) |", "keywords": ["penetration", "summary", "table", "beta decay", "radiation", "dose"], "source": "Part 2"}, {"heading": "Why penetration differs so dramatically", "body": "- **Alpha:** Carries charge +2 and has significant mass → interacts strongly with electrons in matter via Coulomb force → rapidly loses energy → stopped very quickly. Despite being stopped easily, alpha particles deposit all their energy in a very short distance (high Linear Energy Transfer, LET) — very damaging to tissue if the source is inside the body.\n\n- **Beta:** Lighter, travels faster for same energy, charge ±1 → moderately ionising → travels further than alpha but much less than gamma. Also loses energy to bremsstrahlung (braking radiation) when decelerated in matter.\n\n- **Gamma:** No charge, no mass → does not directly ionise; instead interacts via photoelectric effect, Compton scattering, or pair production → penetrates deeply. Intensity follows the inverse square law AND is attenuated exponentially through material. Cannot be fully stopped, only reduced.", "keywords": ["penetration", "differs", "dramatically", "alpha decay", "strong force", "radiation", "dose"], "source": "Part 2"}, {"heading": "Biological significance of penetration", "body": "| Radiation | External source | Internal source (inhaled/ingested) |\n|---|---|---|\n| Alpha | **Harmless** — stopped by dead skin layer | **Very dangerous** — deposits all energy in small tissue volume |\n| Beta | Can burn skin at high doses | Moderately dangerous |\n| Gamma | Most dangerous external source — penetrates whole body | Dangerous but passes through more quickly |\n\n**Radon example:** Rn-222 is an alpha emitter. External to the body, it's harmless. Inhaled into the lung, its alpha particles (and those of its daughters Po-218 and Po-214) damage lung cells directly.\n\n**Smoke detector example:** Am-241 (alpha emitter) is safe in a plastic case — alpha particles can't escape. It would be dangerous if the material were ingested.", "keywords": ["biological", "significance", "penetration", "alpha decay", "radiation", "dose", "applications", "exam"], "source": "Part 2"}, {"heading": "Half-value layer", "body": "The **half-value layer (HVL)** for gamma radiation is the thickness of a material that reduces gamma intensity by 50%.\n\n> I(x) = I₀ × e^(−μx)   where μ = linear attenuation coefficient\n\nHVL = 0.693/μ\n\nFor lead at typical medical gamma energies (~0.14 MeV from Tc-99m): HVL ≈ 0.4 mm Pb\nFor concrete at high energies (~1 MeV): HVL ≈ 10 cm\n\n---", "keywords": ["half", "value", "layer", "activity", "tc-99m", "radiation"], "source": "Part 2"}, {"heading": "Absorbed Dose", "body": "| Unit | Definition | Notes |\n|---|---|---|\n| **Gray (Gy)** | 1 joule of energy deposited per kilogram of tissue | SI unit of absorbed dose |\n| **Rad** | 0.01 Gy | Older unit, still used in USA |\n\n> Absorbed dose (Gy) = Energy deposited (J) / Mass of tissue (kg)", "keywords": ["absorbed", "dose"], "source": "Part 2"}, {"heading": "Equivalent Dose (accounts for radiation type)", "body": "Different radiations cause different amounts of biological damage per unit energy deposited.\n\n> Equivalent dose (Sv) = Absorbed dose (Gy) × Radiation weighting factor (w_R)\n\n| Radiation type | Weighting factor (w_R) |\n|---|---|\n| X-rays, gamma, beta | 1 |\n| Alpha particles | 20 |\n| Protons | 2 |\n| Heavy ions | 20 |\n\nUnit: **Sievert (Sv)** — SI unit.  Older unit: **rem** (1 Sv = 100 rem).", "keywords": ["equivalent", "dose", "accounts", "radiation", "type", "alpha decay"], "source": "Part 2"}, {"heading": "Why alpha has weighting factor 20", "body": "Alpha particles deposit energy much more densely along their path (high LET) than gamma rays. Even though they travel only micrometres in tissue, they cause much more DNA damage per unit absorbed energy. A 1 Gy alpha dose causes ~20× more biological harm than a 1 Gy gamma dose → hence w_R = 20.", "keywords": ["alpha", "weighting", "factor", "alpha decay", "gamma", "radiation", "dose"], "source": "Part 2"}, {"heading": "Effective Dose (accounts for tissue sensitivity too)", "body": "> Effective dose (Sv) = Σ [Equivalent dose × Tissue weighting factor (w_T)]\n\nDifferent organs have different radiosensitivities (e.g., bone marrow, lungs, stomach are more sensitive than bone surface, skin, brain).", "keywords": ["effective", "dose", "accounts", "tissue", "sensitivity"], "source": "Part 2"}, {"heading": "Typical dose values for context", "body": "| Source | Typical effective dose |\n|---|---|\n| Chest X-ray | ~0.02 mSv |\n| CT scan (abdomen) | ~10 mSv |\n| Annual background radiation (UK average) | ~2.7 mSv |\n| Tc-99m bone scan | ~3–4 mSv |\n| Long-haul flight (~10 hours) | ~0.05 mSv |\n| Annual occupational limit (radiation workers) | 20 mSv |\n| Acute dose causing radiation sickness | >1000 mSv (1 Sv) |\n\n---", "keywords": ["typical", "dose", "values", "context", "tc-99m", "radiation"], "source": "Part 2"}, {"heading": "9. THE THREE NATURAL DECAY SERIES", "body": "## 9. THE THREE NATURAL DECAY SERIES\n\nThree naturally occurring radioactive decay chains exist — they all start with very long-lived isotopes and end with stable lead isotopes (or bismuth-209).", "keywords": ["three", "natural", "decay", "series", "u-238", "isotope", "radioactive decay"], "source": "Part 2"}, {"heading": "Series 1: Uranium-238 Series (4n+2 series)", "body": "- **Parent:** U-238 (t½ = 4.47 × 10⁹ y)\n- **End product:** Pb-206 (stable)\n- **Steps:** 14 (8α + 6β⁻)\n- **All members have A = 4n + 2** (where n is an integer)\n- Notable member: Ra-226 (t½ = 1600 y) → Rn-222 (t½ = 3.82 d)\n- This chain is covered in full in Part 1 of this document.", "keywords": ["series", "uranium", "238", "beta decay", "half-life", "u-238"], "source": "Part 2"}, {"heading": "Series 2: Thorium-232 Series (4n series)", "body": "- **Parent:** Th-232 (t½ = 1.40 × 10¹⁰ y)\n- **End product:** Pb-208 (stable)\n- **Steps:** 10 (6α + 4β⁻)\n- **All members have A divisible by 4** (A = 4n)\n- Notable member: Ra-228 → Rn-220 (radon from thorium chain)\n\n| Step | Isotope | Decay | Half-life |\n|---|---|---|---|\n| 1 | Th-232 | α | 1.40 × 10¹⁰ y |\n| 2 | Ra-228 | β⁻ | 5.75 y |\n| 3 | Ac-228 | β⁻ | 6.15 h |\n| 4 | Th-228 | α | 1.91 y |\n| 5 | Ra-224 | α | 3.66 d |\n| 6 | Rn-220 | α | 55.6 s |\n| 7 | Po-216 | α | 0.145 s |\n| 8 | Pb-212 | β⁻ | 10.6 h |\n| 9 | Bi-212 | α + β⁻ (branching) | 60.6 min |\n| 10 | Po-212 / Tl-208 | α / β⁻ | → Pb-208 (stable) |", "keywords": ["series", "thorium", "232", "beta decay", "half-life", "isotope"], "source": "Part 2"}, {"heading": "Series 3: Uranium-235 / Actinium Series (4n+3 series)", "body": "- **Parent:** U-235 (t½ = 7.04 × 10⁸ y)\n- **End product:** Pb-207 (stable)\n- **Steps:** 11 (7α + 4β⁻)\n- **All members have A = 4n + 3**\n- Notable member: Ac-227 (gave the series its alternative name)", "keywords": ["series", "uranium", "235", "actinium", "beta decay", "half-life", "reactor"], "source": "Part 2"}, {"heading": "Why only three natural series?", "body": "There are four possible mathematical series for heavy nuclei: 4n, 4n+1, 4n+2, 4n+3. The fourth (4n+1) would start with Np-237 (t½ = 2.14 × 10⁶ y). This half-life is long enough that Np-237 existed when Earth formed, but short enough (relative to Earth's 4.5 Gy age) that it has completely decayed away and no longer exists naturally. The 4n+1 series is sometimes called the neptunium series and ends at stable Bi-209.", "keywords": ["three", "natural", "series", "half-life", "dose"], "source": "Part 2"}, {"heading": "Why all heavy decay chains eventually end at lead", "body": "Lead sits near (Z=82) or at the end of the valley of stability for heavy elements. Its isotopes Pb-206, Pb-207, and Pb-208 are all doubly or near-doubly magic, making them exceptionally stable. The only exception is Bi-209 (end of the neptunium series), which is technically radioactive via alpha decay with t½ ≈ 2 × 10¹⁹ years — far longer than the age of the universe.\n\n---", "keywords": ["heavy", "decay", "chains", "eventually", "end", "lead", "alpha decay", "half-life", "valley of stability", "radiation", "isotope"], "source": "Part 2"}, {"heading": "Secular Equilibrium (covered in Part 1 — extended here)", "body": "**Condition:** Parent half-life >> daughter half-life (by a factor of ~100 or more)\n\n**Result:** After ~10 daughter half-lives, the daughter's activity equals the parent's activity.\n> A_daughter = A_parent\n\n**Example:** ²²⁶Ra (t½=1600 y) → ²²²Rn (t½=3.82 d)\nAfter ~38 days (~10 half-lives of Rn), the Rn activity exactly equals the Ra activity.\nThe parent (Ra) decays so slowly relative to the daughter (Rn) that the parent's activity is essentially constant — it acts like an inexhaustible source from the daughter's perspective.", "keywords": ["secular", "equilibrium", "covered", "part", "extended", "half-life", "activity", "exam"], "source": "Part 2"}, {"heading": "Transient Equilibrium", "body": "**Condition:** Parent half-life > daughter half-life, but not by a huge factor (ratio ~10–100×)\n\n**Result:** After ~10 daughter half-lives, the daughter's activity exceeds the parent's activity by a constant factor.\n> A_daughter / A_parent = t½(parent) / [t½(parent) − t½(daughter)]\n\nThe ratio is greater than 1 — the daughter appears MORE active than the parent, which seems paradoxical but is explained by the fact that the parent is also significantly decaying.\n\n**Example:** ⁹⁹Mo (t½=66 h) → ⁹⁹ᵐTc (t½=6 h)\nMo-99 is in hospital generators. After equilibrium:\n> A(Tc-99m) / A(Mo-99) = 66/(66−6) = 66/60 = 1.10\n\nTc-99m reaches ~110% of the Mo-99 activity — it can be \"milked\" from the generator.", "keywords": ["transient", "equilibrium", "half-life", "activity", "tc-99m", "exam"], "source": "Part 2"}, {"heading": "No Equilibrium", "body": "**Condition:** Daughter half-life > parent half-life\n\nNo equilibrium is reached. The daughter builds up initially, reaches a peak, and then the daughter activity dominates.", "keywords": ["equilibrium", "half-life", "activity"], "source": "Part 2"}, {"heading": "Summary", "body": "| Type | Condition | Daughter activity at equilibrium |\n|---|---|---|\n| Secular | t½(parent) >> t½(daughter) | A_d = A_p |\n| Transient | t½(parent) > t½(daughter) | A_d > A_p (by fixed ratio) |\n| None | t½(parent) < t½(daughter) | No equilibrium — daughter dominates eventually |\n\n---", "keywords": ["summary", "half-life", "activity"], "source": "Part 2"}, {"heading": "The Liquid Drop Model", "body": "**Concept:** Treats the nucleus as a droplet of incompressible nuclear fluid. Nucleons interact with all nearest neighbours equally, like molecules in a liquid.\n\n**Strengths:**\n- Explains why binding energy ∝ A (volume term)\n- Predicts the existence of the surface energy correction\n- Explains general fission barrier\n- The SEMF is a mathematical expression of this model\n\n**Weaknesses:**\n- Cannot explain magic numbers\n- Cannot predict nuclear spins and parities\n- Underestimates binding energy at magic numbers\n- Cannot explain ground state properties of individual nuclei\n- Does not capture quantum mechanical shell structure", "keywords": ["liquid", "drop", "model", "binding energy", "semf", "shell model", "fission", "dose"], "source": "Part 2"}, {"heading": "The Nuclear Shell Model", "body": "**Concept (Goeppert Mayer, 1949):** Each nucleon moves independently in an average potential created by all other nucleons. Nucleons occupy discrete quantum energy levels, just like electrons in atoms.\n\n**The critical addition:** A spin-orbit coupling term (strong in nuclei, much weaker in atoms) splits energy levels and produces the correct magic numbers.\n\n**Strengths:**\n- Explains magic numbers (2, 8, 20, 28, 50, 82, 126) as filled shells\n- Predicts nuclear ground state spins and parities\n- Explains extra stability of doubly magic nuclei\n- Explains anomalously many stable isotopes at tin (Z=50)\n\n**Weaknesses:**\n- Less useful for collective nuclear behavior (rotations, vibrations)\n- The \"average potential\" approximation breaks down for some nuclei\n- Shell closures less sharp for very heavy nuclei", "keywords": ["nuclear", "shell", "model", "shell model", "dose", "isotope"], "source": "Part 2"}, {"heading": "Comparison table", "body": "| Feature | Liquid Drop Model | Shell Model |\n|---|---|---|\n| Basis | Classical — nuclear fluid | Quantum mechanical — energy levels |\n| Magic numbers | Cannot explain | Predicts correctly |\n| SEMF | Derived from this model | Supplements SEMF near magic numbers |\n| Nuclear spin | Cannot predict | Predicts ground state spin |\n| Best for | Bulk properties, fission | Individual nuclear properties |\n| Developed by | Bohr, Wheeler (~1939) | Goeppert Mayer, Jensen (1949) |\n| Nobel Prize | N/A for liquid drop specifically | Goeppert Mayer and Jensen (1963) |", "keywords": ["comparison", "table", "activity", "semf", "shell model", "fission", "dose"], "source": "Part 2"}, {"heading": "Why are both needed?", "body": "Neither model works alone. For calculating binding energies and fission barriers, the liquid drop model (SEMF) is the starting point. But near magic numbers, shell corrections must be added. Modern nuclear physics uses the **nuclear shell model** for structure and the **liquid drop model** for reactions.\n\n---", "keywords": ["both", "needed", "semf", "shell model", "fission"], "source": "Part 2"}, {"heading": "What the weak force does", "body": "The weak nuclear force is the only fundamental force that can change the **flavour** of quarks. In beta decay:\n\n- **β⁻ decay:** A **down quark** in a neutron converts to an **up quark**, turning the neutron into a proton.\n  > d → u + W⁻ (virtual W boson emitted)\n  > W⁻ → e⁻ + ν̄_e\n\n- **β⁺ decay:** An **up quark** in a proton converts to a **down quark**, turning the proton into a neutron.\n  > u → d + W⁺\n  > W⁺ → e⁺ + ν_e", "keywords": ["weak", "force", "beta decay", "radiation", "forces"], "source": "Part 2"}, {"heading": "Properties of the weak force", "body": "| Property | Value/Description |\n|---|---|\n| Range | ~10⁻¹⁸ m (0.001 fm) — shorter than nuclear size |\n| Mediating bosons | W⁺, W⁻ (charge-changing), Z⁰ (neutral) |\n| Mass of W boson | ~80 GeV/c² (very heavy → very short range) |\n| Relative strength | ~10⁻⁶ compared to strong force at nuclear distances |\n| Distinguishing feature | Violates parity (P), charge conjugation (C), and CP symmetry (partially) |\n| Acts on | All fermions (quarks and leptons) |", "keywords": ["properties", "weak", "force", "strong force", "parity", "historical"], "source": "Part 2"}, {"heading": "Why beta decay is slow relative to gamma decay", "body": "The weak force is ~10⁶ times weaker than the electromagnetic force at nuclear distances. Gamma decay (electromagnetic) typically occurs in ~10⁻¹² s. Beta decay (weak) has half-lives ranging from milliseconds to billions of years. The virtual W boson that mediates beta decay has mass ~80 GeV — far larger than the nuclear energy scales of MeV — making it very \"off-shell\" and suppressing the interaction rate.", "keywords": ["beta", "decay", "slow", "relative", "gamma", "beta decay", "radiation", "dose", "forces"], "source": "Part 2"}, {"heading": "Lepton number conservation in beta decay", "body": "Leptons (electrons, positrons, neutrinos) have lepton number L:\n- e⁻ and ν_e: L = +1\n- e⁺ and ν̄_e: L = −1\n\nIn β⁻ decay: e⁻ (L=+1) + ν̄_e (L=−1) → net lepton number = 0 ✓\nIn β⁺ decay: e⁺ (L=−1) + ν_e (L=+1) → net lepton number = 0 ✓\nIn EC: captured e⁻ (L=+1) + emitted ν_e (L=−1) → net lepton number = 0 ✓\n\nLepton number is conserved in all weak interactions.\n\n---", "keywords": ["lepton", "number", "conservation", "beta", "decay", "beta decay", "neutrino"], "source": "Part 2"}, {"heading": "Method 1: Using Z and A rules", "body": "1. Look up the element symbol for the new Z using the periodic table.\n2. Apply the ΔZ and ΔA for the decay mode.\n\n**Example: What is the daughter of Bi-214 (Z=83, A=214) undergoing β⁻ decay?**\n- β⁻: Z → Z+1, A unchanged\n- New Z = 84 → element is **Polonium (Po)**\n- Daughter: **Po-214** ✓ (matches the U-238 decay chain)\n\n**Example: What is the daughter of Ra-226 (Z=88, A=226) undergoing α decay?**\n- α: Z → Z−2, A → A−4\n- New Z = 86 → element is **Radon (Rn)**\n- New A = 222\n- Daughter: **Rn-222** ✓\n\n**Example: What is the daughter of F-18 (Z=9, A=18) undergoing β⁺ decay?**\n- β⁺: Z → Z−1, A unchanged\n- New Z = 8 → element is **Oxygen (O)**\n- Daughter: **O-18** ✓ (as used in PET scanning)", "keywords": ["method", "using", "rules", "alpha decay", "beta decay", "u-238", "pet", "exam", "radioactive decay"], "source": "Part 2"}, {"heading": "Method 2: Balancing the nuclear equation", "body": "Write the equation and ensure Z and A balance on both sides.\n\n**Example: Complete the equation:** ²⁰⁸₈₃Bi → ? + ⁴₂He\n\n- A: 208 = A_daughter + 4 → A_daughter = 204\n- Z: 83 = Z_daughter + 2 → Z_daughter = 81 → element is **Thallium (Tl)**\n- Answer: ²⁰⁴₈₁Tl", "keywords": ["method", "balancing", "nuclear", "equation", "exam"], "source": "Part 2"}, {"heading": "Periodic Table quick reference for common elements in decay chains", "body": "| Z | Element | Symbol | Z | Element | Symbol |\n|---|---|---|---|---|---|\n| 82 | Lead | Pb | 88 | Radium | Ra |\n| 83 | Bismuth | Bi | 89 | Actinium | Ac |\n| 84 | Polonium | Po | 90 | Thorium | Th |\n| 85 | Astatine | At | 91 | Protactinium | Pa |\n| 86 | Radon | Rn | 92 | Uranium | U |\n| 87 | Francium | Fr | 93 | Neptunium | Np |\n\n---", "keywords": ["periodic", "table", "quick", "reference", "common", "elements", "decay", "chains", "activity"], "source": "Part 2"}, {"heading": "How C-14 is produced", "body": "Cosmic rays (mainly high-energy protons) hit nitrogen-14 in the upper atmosphere:\n> ¹⁴₇N + ¹₀n → ¹⁴₆C + ¹₁H\n\nThe C-14 oxidises to ¹⁴CO₂, which enters the carbon cycle. All living organisms maintain a constant ¹⁴C/¹²C ratio by exchanging carbon with the environment.", "keywords": ["produced", "carbon-14", "dose"], "source": "Part 2"}, {"heading": "The fundamental assumption", "body": "At death, carbon exchange stops and ¹⁴C begins to decrease with t½ = 5,730 years. We assume the **initial ¹⁴C/¹²C ratio** is the same as today's atmospheric ratio (~1.2 × 10⁻¹²).", "keywords": ["fundamental", "assumption", "half-life"], "source": "Part 2"}, {"heading": "Limitations", "body": "| Limitation | Explanation |\n|---|---|\n| **Maximum range ~50,000 years** | After ~8–9 half-lives, so little ¹⁴C remains that measurement error dominates |\n| **Requires calibration** | Atmospheric ¹⁴C production has not been constant — solar activity and Earth's magnetic field variation affect cosmic ray flux → calibration curves needed |\n| **Reservoir effects** | Marine organisms incorporate old carbon dissolved in deep ocean → apparent age offset of ~400–500 years for marine samples |\n| **Industrial effect** | Burning fossil fuels (dead carbon, no ¹⁴C) dilutes atmospheric ¹⁴C → samples after ~1850 give artificially old dates (Suess effect) |\n| **Nuclear testing** | Atmospheric nuclear tests 1945–1963 roughly doubled atmospheric ¹⁴C → samples from after ~1963 show anomalously young dates |\n| **Closed system assumption** | If carbon has leached in or out since death, the date is wrong |\n| **Only for organic material** | Cannot date rock, minerals (use U-Pb, K-Ar, Rb-Sr for these) |", "keywords": ["limitations", "activity"], "source": "Part 2"}, {"heading": "Calibration", "body": "The **IntCal** calibration curve corrects for variations in atmospheric ¹⁴C. Built using:\n- Tree ring records (dendrochronology) for the last ~14,000 years\n- Coral records, lake sediments for older periods\n- Marine sediment cores and cave formations for up to ~55,000 years\n\nProperly calibrated radiocarbon dates include error bars reflecting calibration uncertainty.", "keywords": ["calibration", "carbon-14", "dose"], "source": "Part 2"}, {"heading": "When to use which dating method", "body": "| Method | Based on | Range | Best for |\n|---|---|---|---|\n| ¹⁴C / Radiocarbon | ¹⁴C → ¹⁴N (β⁻, t½=5730 y) | 100–50,000 years | Organic materials (wood, bone, charcoal) |\n| ²³⁸U → ²⁰⁶Pb | U-238 decay chain | 10 My – 4.5 Gy | Rocks, minerals, meteorites |\n| ⁴⁰K → ⁴⁰Ar | K-40 EC/β⁺, t½=1.25 Gy | 100,000 y – 4.5 Gy | Volcanic rocks |\n| ⁸⁷Rb → ⁸⁷Sr | Rb-87 β⁻, t½=48.8 Gy | 10 My – 4.5 Gy | Ancient rocks, meteorites |\n| ²³²Th → ²⁰⁸Pb | Th-232 decay chain | 1 My – 14 Gy | Ancient rocks |\n| Thermoluminescence | Accumulated radiation damage | 1,000–500,000 years | Minerals (pottery, sediments) |\n| Cosmogenic ¹⁰Be, ²⁶Al | Spallation products | 10,000–5 My | Surface exposure dating |\n\n---", "keywords": ["use", "which", "dating", "method", "beta decay", "half-life", "activity", "u-238", "carbon-14", "radiation", "dose"], "source": "Part 2"}, {"heading": "15. HISTORICAL FIGURES", "body": "## 15. HISTORICAL FIGURES\n\nEvery scientist mentioned in Chapter 8 or closely associated with its content:", "keywords": ["historical", "figures", "activity"], "source": "Part 2"}, {"heading": "Henri Becquerel (1852–1908)", "body": "- **Contribution:** Discovered radioactivity in 1896, accidentally finding that uranium salts exposed photographic plates without light.\n- **Nobel Prize:** Physics 1903 (shared with Pierre and Marie Curie).\n- **Legacy:** The SI unit of activity, the becquerel (Bq), is named after him.", "keywords": ["henri", "becquerel", "1852", "1908", "activity", "historical", "radioactive decay"], "source": "Part 2"}, {"heading": "Marie Curie (1867–1934)", "body": "- **Contribution:** Coined the term \"radioactivity.\" Discovered polonium and radium. Systematically studied radioactive elements. First person to win two Nobel Prizes.\n- **Nobel Prizes:** Physics 1903 (with Becquerel and Pierre Curie); Chemistry 1911 (for discovery of radium and polonium).\n- **Legacy:** The curie (Ci), the older unit of radioactivity, is named after her.", "keywords": ["marie", "curie", "1867", "1934", "activity", "historical", "radioactive decay"], "source": "Part 2"}, {"heading": "Pierre Curie (1859–1906)", "body": "- **Contribution:** Worked with Marie Curie on radioactivity; showed that radioactive decay produces heat.\n- **Nobel Prize:** Physics 1903.", "keywords": ["pierre", "curie", "1859", "1906", "activity", "historical", "radioactive decay"], "source": "Part 2"}, {"heading": "Ernest Rutherford (1871–1937)", "body": "- **Contribution:** Distinguished alpha and beta radiation (1899). Discovered the nuclear model of the atom (gold foil experiment, 1909). First achieved artificial nuclear reaction (1919). Recognised gamma radiation as distinct. Coined the terms \"alpha,\" \"beta,\" and \"proton.\"\n- **Nobel Prize:** Chemistry 1908 (for radioactivity research, ironically before discovering the nucleus).", "keywords": ["ernest", "rutherford", "1871", "1937", "activity", "radiation", "radioactive decay"], "source": "Part 2"}, {"heading": "Frederick Soddy (1877–1956)", "body": "- **Contribution:** Worked with Rutherford to show that radioactive decay transforms one element into another. Coined the term \"isotope\" (1913). Developed the radioactive displacement law.\n- **Nobel Prize:** Chemistry 1921.", "keywords": ["frederick", "soddy", "1877", "1956", "isotope", "historical", "radioactive decay"], "source": "Part 2"}, {"heading": "George Gamow (1904–1968)", "body": "- **Contribution:** Explained alpha decay as quantum tunnelling in 1928 — one of the first applications of quantum mechanics to nuclear physics.\n- **Legacy:** Also explained stellar nucleosynthesis, the Big Bang model, and proposed the \"Big Bang\" as a term.", "keywords": ["george", "gamow", "1904", "1968", "alpha decay", "quantum tunnelling", "radiation", "applications"], "source": "Part 2"}, {"heading": "Wolfgang Pauli (1900–1958)", "body": "- **Contribution:** Postulated the existence of the neutrino in 1930 to explain the continuous beta spectrum and conserve energy/momentum/lepton number in beta decay.\n- **Nobel Prize:** Physics 1945 (for the exclusion principle).\n- **Note:** He famously said the neutrino was \"a particle I cannot detect\" — it took 26 years to confirm experimentally.", "keywords": ["wolfgang", "pauli", "1900", "1958", "beta decay", "activity", "neutrino", "radiation", "dose", "conservation"], "source": "Part 2"}, {"heading": "Enrico Fermi (1901–1954)", "body": "- **Contribution:** Developed the theory of beta decay (1934) incorporating Pauli's neutrino. Built the first artificial nuclear reactor (Chicago Pile-1, 1942). Induced the first controlled nuclear chain reaction.\n- **Nobel Prize:** Physics 1938 (for neutron-induced nuclear reactions).", "keywords": ["enrico", "fermi", "1901", "1954", "beta decay", "activity", "neutrino", "reactor", "radiation"], "source": "Part 2"}, {"heading": "Frederick Reines (1918–1998) and Clyde Cowan (1919–1974)", "body": "- **Contribution:** First direct experimental detection of the neutrino (antineutrino) in 1956, confirming Pauli's 1930 prediction.\n- **Nobel Prize:** Reines received Nobel Prize in Physics 1995 (Cowan had died).", "keywords": ["frederick", "reines", "1918", "1998", "clyde", "cowan", "1919", "1974", "neutrino"], "source": "Part 2"}, {"heading": "Maria Goeppert Mayer (1906–1972)", "body": "- **Contribution:** Developed the nuclear shell model with spin-orbit coupling (1949), explaining magic numbers and the structure of atomic nuclei.\n- **Nobel Prize:** Physics 1963 (shared with Hans Jensen and Eugene Wigner). Only the second woman to win the Nobel Prize in Physics.", "keywords": ["maria", "goeppert", "mayer", "1906", "1972", "shell model"], "source": "Part 2"}, {"heading": "J. Hans D. Jensen (1907–1973)", "body": "- **Contribution:** Independently developed the nuclear shell model with spin-orbit coupling simultaneously with Goeppert Mayer.\n- **Nobel Prize:** Physics 1963.", "keywords": ["hans", "jensen", "1907", "1973", "shell model"], "source": "Part 2"}, {"heading": "Carl Friedrich von Weizsäcker (1912–2007)", "body": "- **Contribution:** Developed the semi-empirical mass formula (SEMF) in 1935, which quantitatively predicts nuclear binding energies based on five physical terms.\n- **Legacy:** The SEMF is often called the \"Weizsäcker formula.\"", "keywords": ["carl", "friedrich", "von", "weizsäcker", "1912", "2007", "semf"], "source": "Part 2"}, {"heading": "Hans Bethe (1906–2005)", "body": "- **Contribution:** Explained energy production in stars via nuclear fusion (1939), for which he won the Nobel Prize.\n- **Nobel Prize:** Physics 1967.", "keywords": ["hans", "bethe", "1906", "2005", "fusion", "dose"], "source": "Part 2"}, {"heading": "Tsung-Dao Lee (1926–) and Chen-Ning Yang (1922–)", "body": "- **Contribution:** Theorised in 1956 that the weak force might violate parity (mirror symmetry) — a radical proposal contradicting the assumed universality of parity conservation.\n- **Nobel Prize:** Physics 1957 — awarded remarkably quickly because Wu's experimental confirmation was so decisive.", "keywords": ["tsung", "dao", "lee", "1926", "chen", "ning", "yang", "1922", "activity", "parity", "conservation"], "source": "Part 2"}, {"heading": "Chien-Shiung Wu (1912–1997)", "body": "- **Contribution:** Experimentally confirmed parity violation in beta decay (1956) using aligned cobalt-60 at near-absolute-zero temperatures. Beta particles were emitted preferentially in one direction, proving the weak force breaks mirror symmetry.\n- **Recognition:** Did not receive the Nobel Prize despite the discovery being fundamental — widely considered one of the most significant omissions in Nobel Prize history.\n- **Legacy:** Called the \"First Lady of Physics\" and the \"Chinese Marie Curie.\" The Wu experiment is one of the most celebrated in physics.", "keywords": ["chien", "shiung", "1912", "1997", "beta decay", "activity", "radiation", "parity", "historical"], "source": "Part 2"}, {"heading": "James Chadwick (1891–1974)", "body": "- **Contribution:** Discovered the neutron in 1932, explaining why nuclei are heavier than their proton count alone would suggest.\n- **Nobel Prize:** Physics 1935.", "keywords": ["james", "chadwick", "1891", "1974"], "source": "Part 2"}, {"heading": "Lise Meitner (1878–1968) and Otto Hahn (1879–1968)", "body": "- **Contribution:** Meitner (with Otto Frisch) provided the theoretical explanation of nuclear fission in 1938/39. Otto Hahn performed the experiments that first demonstrated uranium fission.\n- **Nobel Prize:** Hahn received Nobel Prize in Chemistry 1944. Meitner was controversially overlooked — another famous Nobel omission. Element 109 (meitnerium) is named after her.\n\n---", "keywords": ["lise", "meitner", "1878", "1968", "otto", "hahn", "1879", "fission", "historical"], "source": "Part 2"}, {"heading": "Example 1: Multi-step decay calculation", "body": "**Problem:** A sample of Ra-226 (t½ = 1600 y) has an initial activity of 1.00 × 10⁶ Bq. Assuming secular equilibrium, what is the activity of Rn-222 (t½ = 3.82 d) in the sample after 5000 years?\n\n**Solution:**\n\nStep 1 — Activity of Ra-226 after 5000 years:\n> A_Ra(t) = A₀ × (½)^(t/t½) = 1.00×10⁶ × (½)^(5000/1600)\n> = 1.00×10⁶ × (½)^3.125\n> = 1.00×10⁶ × 0.1161\n> = **1.16 × 10⁵ Bq**\n\nStep 2 — Activity of Rn-222 at secular equilibrium:\n> A_Rn = A_Ra (at secular equilibrium, since t >> t½(Rn) = 3.82 d)\n> = **1.16 × 10⁵ Bq**\n\n**Answer:** 1.16 × 10⁵ Bq (same as Ra-226 activity due to secular equilibrium)\n\n---", "keywords": ["example", "multi", "step", "decay", "calculation", "half-life", "activity", "secular equilibrium"], "source": "Part 2"}, {"heading": "Example 2: Q-value and spontaneity check", "body": "**Problem:** Is the decay ²³⁵₉₂U → ²³¹₉₀Th + ⁴₂He spontaneous?\n- m(U-235) = 235.0439 u\n- m(Th-231) = 231.0363 u\n- m(⁴He) = 4.0026 u\n\n**Solution:**\n\n> Δm = 235.0439 − 231.0363 − 4.0026 = 235.0439 − 235.0389 = +0.0050 u\n\nSince Δm > 0, Q > 0:\n> Q = 0.0050 × 931.5 = **4.66 MeV**\n\nSince Q > 0, the decay is **spontaneous (energetically allowed)**.\n\n---", "keywords": ["example", "value", "spontaneity", "check", "reactor"], "source": "Part 2"}, {"heading": "Example 3: Number of nuclei from activity", "body": "**Problem:** A Tc-99m source has activity 500 MBq. How many Tc-99m nuclei are present? (t½ = 6.0 h)\n\n**Solution:**\n\n> λ = 0.693 / t½ = 0.693 / (6 × 3600 s) = 0.693 / 21600 = 3.208 × 10⁻⁵ s⁻¹\n\n> A = λN → N = A/λ\n\n> N = (500 × 10⁶) / (3.208 × 10⁻⁵) = **1.56 × 10¹³ nuclei**\n\nThis is a tiny amount of material (~2.6 × 10⁻¹² g or 2.6 picograms) yet produces 500 million decays per second.\n\n---", "keywords": ["example", "number", "nuclei", "activity", "half-life", "tc-99m"], "source": "Part 2"}, {"heading": "Example 4: Age of a rock from U-Pb ratio", "body": "**Problem:** A rock sample contains N(²⁰⁶Pb)/N(²³⁸U) = 0.45. Assuming all Pb-206 came from U-238 decay and no Pb-206 was present originally, what is the age of the rock?\n\nt½(U-238) = 4.47 × 10⁹ years → λ = 0.693 / (4.47 × 10⁹) = 1.55 × 10⁻¹⁰ y⁻¹\n\n**Solution:**\n\nUsing: t = (1/λ) × ln(1 + N_Pb/N_U)\n> t = (1 / 1.55×10⁻¹⁰) × ln(1 + 0.45)\n> t = 6.45×10⁹ × ln(1.45)\n> t = 6.45×10⁹ × 0.3716\n> t = **2.40 × 10⁹ years = 2.4 billion years**\n\n---", "keywords": ["example", "age", "rock", "ratio", "half-life", "u-238"], "source": "Part 2"}, {"heading": "Example 5: Comparing stability of two nuclei using all four factors", "body": "**Problem:** Compare the stability of ⁴⁰₁₉K (Z=19, N=21) and ⁴⁰₂₀Ca (Z=20, N=20).\n\n**Analysis:**\n\n| Factor | ⁴⁰K | ⁴⁰Ca |\n|---|---|---|\n| N/Z ratio | 21/19 = 1.105 | 20/20 = 1.0 |\n| Even/odd | Odd Z, odd N → odd-odd (least stable) | Even Z, even N → even-even (most stable) |\n| Magic numbers | Neither Z=19 nor N=21 is magic | Z=20 is magic! N=20 is magic! **Doubly magic!** |\n| BE/A (approximate) | Lower | Higher |\n\n**Conclusion:** ⁴⁰Ca is exceptionally stable — it is a doubly magic nucleus (Z=20, N=20) and even-even. ⁴⁰K is odd-odd, with N/Z slightly above 1, and no magic numbers. Indeed, ⁴⁰K is radioactive (t½ = 1.25 × 10⁹ y, undergoes both β⁻ and electron capture), while ⁴⁰Ca is completely stable.\n\n---", "keywords": ["example", "comparing", "stability", "two", "nuclei", "using", "four", "factors", "beta decay", "half-life", "binding energy", "shell model", "n/z", "pairing"], "source": "Part 2"}, {"heading": "Example 6: Full SEMF calculation for a different nucleus — ²⁰⁸Pb (Z=82, N=126)", "body": "| Term | Calculation | Value |\n|---|---|---|\n| Volume | 15.75 × 208 | +3276.0 MeV |\n| Surface | −17.8 × 208^(2/3) = −17.8 × 35.34 | −629.1 MeV |\n| Coulomb | −0.711 × (82×81) / 208^(1/3) = −0.711 × 6642 / 5.926 | −797.0 MeV |\n| Asymmetry | −23.7 × (126−82)² / 208 = −23.7 × 1936/208 | −220.7 MeV |\n| Pairing | +11.18 / √208 = +11.18 / 14.42 (even-even) | +0.78 MeV |\n| **Total BE** | | **~1630 MeV** |\n| **BE/A** | 1630 / 208 | **~7.84 MeV/nucleon** |\n\nExperimental value: 7.87 MeV/nucleon. Very close. Note that the SEMF slightly underestimates even here — the doubly magic nature of Pb-208 (Z=82, N=126 — both magic) gives extra binding that the SEMF doesn't fully capture.\n\n---", "keywords": ["example", "full", "semf", "calculation", "different", "nucleus", "²⁰⁸pb", "126", "binding energy", "strong force", "pairing"], "source": "Part 2"}, {"heading": "17. COMPLETE GLOSSARY — EVERY TERM DEFINED", "body": "## 17. COMPLETE GLOSSARY — EVERY TERM DEFINED\n\n**Activity (A):** The rate of radioactive decay of a sample, measured in becquerels (Bq = 1 decay per second) or curies (Ci). A = λN.\n\n**Alpha decay (α):** Emission of a helium-4 nucleus (2p + 2n) from a heavy nucleus. Reduces Z by 2, A by 4.\n\n**Alpha particle:** A helium-4 nucleus (⁴He), charge +2, emitted in alpha decay. High LET, low penetration.\n\n**Asymmetry term:** Term in the SEMF penalising nuclei where N ≠ Z, arising from the Pauli exclusion principle. −23.7(N−Z)²/A.\n\n**Atomic mass unit (u):** Unified mass unit. 1 u = 1/12 of mass of ¹²C = 1.66054 × 10⁻²⁷ kg = 931.5 MeV/c².\n\n**Atomic number (Z):** Number of protons in a nucleus. Determines which element it is.\n\n**Baryon number:** Total number of nucleons (protons + neutrons). Conserved in all known interactions.\n\n**Becquerel (Bq):** SI unit of radioactivity. 1 Bq = 1 disintegration per second.\n\n**Beta decay:** Decay via the weak force converting a neutron to a proton (β⁻) or proton to neutron (β⁺ or EC).\n\n**Beta-minus (β⁻) decay:** Emission of an electron and antineutrino from a neutron-rich nucleus. Z increases by 1, A unchanged.\n\n**Beta-plus (β⁺) decay:** Emission of a positron and neutrino from a proton-rich nucleus. Z decreases by 1, A unchanged. Requires Q > 1.022 MeV.\n\n**Binding energy (BE):** Energy required to completely disassemble a nucleus into separate protons and neutrons. BE = Δm × c². Always positive for stable nuclei.\n\n**Binding energy per nucleon (BE/A):** Average binding energy per nucleon. Peaks at ~8.79 MeV for ⁵⁶Fe. Direct measure of nuclear stability.\n\n**Coulomb barrier:** The electrostatic potential energy barrier that a charged particle (e.g., alpha particle) must overcome or tunnel through to escape a nucleus.\n\n**Coulomb repulsion:** Electrostatic repulsion between protons, proportional to Z(Z−1). Long-range (infinite), destabilises heavy nuclei.\n\n**Curie (Ci):** Older unit of activity. 1 Ci = 3.70 × 10¹⁰ Bq (activity of 1 g of ²²⁶Ra).\n\n**Daughter nucleus:** The nucleus produced after a radioactive decay.\n\n**Decay chain:** A sequence of successive radioactive decays from a heavy parent through multiple daughter nuclei until a stable end product is reached.\n\n**Decay constant (λ):** Probability of decay per unit time for a single nucleus. λ = 0.693/t½. Units: s⁻¹.\n\n**Decay series:** One of the three natural radioactive decay chains (U-238, Th-232, U-235 series).\n\n**Doubly magic nucleus:** A nucleus where both Z and N equal magic numbers (e.g., ⁴He, ¹⁶O, ⁴⁰Ca, ²⁰⁸Pb). Exceptionally stable.\n\n**Electron capture (EC):** A proton-rich nucleus captures an inner-shell orbital electron, converting a proton to a neutron. Emits a neutrino and produces characteristic X-rays. Alternative to β⁺ decay.\n\n**Electron (beta particle):** In β⁻ decay, an electron is emitted. Symbol: e⁻ or β⁻. Mass = 0.000549 u.\n\n**Enrichment:** The process of increasing the fraction of U-235 in uranium (from 0.7% natural → 3–5% for reactors, >90% for weapons).\n\n**Even-even nucleus:** Nucleus with even Z and even N. Most stable configuration — 165 stable examples.\n\n**Even-odd nucleus:** Nucleus with even Z and odd N (or vice versa). Moderately stable.\n\n**Exponential decay:** N(t) = N₀e^(−λt). The fundamental law describing radioactive decay.\n\n**Femtometre (fm):** 10⁻¹⁵ metres. The natural length scale of atomic nuclei (1–10 fm).\n\n**Fissile:** Capable of sustaining a chain reaction with slow (thermal) neutrons. Examples: U-235, Pu-239.\n\n**Fission:** Splitting of a heavy nucleus into two smaller fragments, releasing energy because the fragments have higher BE/A.\n\n**Fission fragments:** The two (approximately equal) daughter nuclei produced in fission.\n\n**Fusion:** Combining two light nuclei into a heavier one, releasing energy because the product has higher BE/A.\n\n**Gamma (γ) decay/emission:** Emission of a high-energy photon from an excited nucleus. No change in Z or A. Electromagnetic in nature.\n\n**Gamma ray:** High-energy photon (keV–MeV range) emitted in gamma decay. Most penetrating form of nuclear radiation.\n\n**Geiger-Nuttall law:** Empirical law relating alpha decay half-life to decay energy: log₁₀(T½) = A(Z)/√E + B(Z). Shows extreme sensitivity of half-life to energy.\n\n**Gray (Gy):** SI unit of absorbed radiation dose. 1 Gy = 1 J/kg.\n\n**Half-life (t½):** Time for exactly half of a radioactive sample to decay. t½ = 0.693/λ. Independent of external conditions.\n\n**Hard core:** The repulsive core of the strong force below ~0.5 fm that prevents nucleons from collapsing into each other.\n\n**Isobar:** Nuclides with the same A but different Z (e.g., ¹⁴C and ¹⁴N).\n\n**Isomer (nuclear):** A metastable excited state of a nucleus with the same Z and N as the ground state but longer-lived than typical excited states (t½ > ~1 ns). Indicated by \"m\" superscript (e.g., Tc-99m).\n\n**Isotone:** Nuclides with the same N but different Z (e.g., ¹⁴C and ¹⁶O, both with N=8).\n\n**Isotope:** Nuclides with the same Z (same element) but different N. Examples: ¹²C, ¹³C, ¹⁴C.\n\n**Lepton:** A fundamental particle (electron, positron, neutrino, muon, tau, etc.) not subject to the strong force.\n\n**Lepton number:** Quantum number conserved in all interactions. e⁻ and ν_e have L=+1; e⁺ and ν̄_e have L=−1.\n\n**Liquid drop model:** Nuclear model treating the nucleus as an incompressible liquid drop. Basis of the SEMF.\n\n**Magic number:** Specific number of protons or neutrons (2, 8, 20, 28, 50, 82, 126) giving exceptional nuclear stability due to filled shells in the nuclear shell model.\n\n**Mass defect (Δm):** The difference between the sum of masses of separated nucleons and the actual nuclear mass. Δm × c² = binding energy.\n\n**Mass number (A):** Total number of nucleons (protons + neutrons) in a nucleus. A = Z + N.\n\n**Mean lifetime (τ):** Average time before a nucleus decays. τ = 1/λ = t½/ln2 ≈ 1.443 × t½.\n\n**Neutrino (ν):** Extremely light, neutral lepton emitted in weak decays. Extremely difficult to detect (interacts only via weak force and gravity).\n\n**Neutron:** Electrically neutral nucleon. Mass ≈ 1.008665 u. Provides strong-force binding without Coulomb repulsion.\n\n**Neutron number (N):** Number of neutrons in a nucleus. N = A − Z.\n\n**Nuclear shell model:** Quantum mechanical model treating nucleons as occupying discrete energy levels in a nuclear potential with spin-orbit coupling. Explains magic numbers.\n\n**Nucleon:** Generic term for proton or neutron.\n\n**Nucleus (plural: nuclei):** The dense, positively charged core of an atom, containing all protons and neutrons. Size ~1–10 fm.\n\n**Nuclide:** A specific nuclear species characterised by a unique combination of Z and N.\n\n**Odd-odd nucleus:** Nucleus with odd Z and odd N. Least stable — only 4 stable odd-odd nuclei (¹H, ⁶Li, ¹⁰B, ¹⁴N).\n\n**Pairing energy (δ):** Extra binding for even-even nuclei (both nucleon types fully paired). SEMF pairing term: ±11.18/√A MeV.\n\n**Parent nucleus:** The original nucleus before radioactive decay.\n\n**Parity:** Symmetry under spatial reflection (mirror image). Conserved by strong and electromagnetic forces, but **violated by the weak force**.\n\n**Parity violation:** The discovery (Wu, 1956) that the weak force does not respect mirror symmetry.\n\n**PET (Positron Emission Tomography):** Medical imaging technique using β⁺ emitters (e.g., ¹⁸F). Positron annihilation produces two coincident 511 keV gamma rays detected to build 3D metabolic images.\n\n**Positron (e⁺):** The antiparticle of the electron. Same mass (0.000549 u = 0.511 MeV/c²), charge +1. Emitted in β⁺ decay. Annihilates with an electron to produce two 511 keV gamma rays.\n\n**Proton:** Positively charged nucleon. Charge +e, mass ≈ 1.007276 u.\n\n**Q-value:** Energy released in a nuclear decay reaction. Q = Δm × c² = (m_parent − m_products) × 931.5 MeV/u. If Q > 0, decay is energetically possible.\n\n**Quantum tunnelling:** Quantum mechanical phenomenon where a particle passes through a classically forbidden energy barrier with nonzero probability. Explains alpha decay.\n\n**Radionuclide:** A radioactive nuclide (one that undergoes radioactive decay).\n\n**Radiometric dating:** Using known radioactive decay rates to determine the age of materials.\n\n**Secular equilibrium:** State in a decay chain where, if t½(parent) >> t½(daughter), each daughter's activity equals the parent's activity.\n\n**Semi-empirical mass formula (SEMF):** Also called Weizsäcker formula. Equation predicting nuclear binding energy as a sum of volume, surface, Coulomb, asymmetry, and pairing terms.\n\n**Sievert (Sv):** SI unit of radiation equivalent dose. Sv = Gy × weighting factor.\n\n**Specific activity:** Activity per unit mass of a radionuclide. Short half-life → high specific activity.\n\n**Spontaneous fission:** Spontaneous splitting of a very heavy nucleus (Z ≥ 100) into two fragments without any trigger.\n\n**Strong nuclear force:** Short-range (~1–3 fm) force acting between all nucleon pairs (charge independent). ~100× stronger than EM at 1 fm. Provides nuclear binding; becomes repulsive below ~0.5 fm.\n\n**Technetium-99m (Tc-99m):** Most widely used diagnostic radioisotope. Metastable isomer of Tc-99. t½ = 6 h, pure γ emitter (140 keV). Used in ~80% of nuclear medicine scans.\n\n**Transient equilibrium:** State where t½(parent) > t½(daughter) but not by a large factor. Daughter activity exceeds parent activity by a fixed ratio at equilibrium.\n\n**Valley of stability:** The curved band of stable nuclides on an N-Z plot. Isotopes outside it are radioactive.\n\n**Weak nuclear force:** Short-range force (~0.001 fm) mediated by W⁺, W⁻, Z bosons. Responsible for all beta decay. Only force that can change quark flavour. Violates parity.\n\n**Weizsäcker formula:** Another name for the semi-empirical mass formula (SEMF), after Carl Friedrich von Weizsäcker who derived it in 1935.\n\n**W and Z bosons:** The massive gauge bosons that mediate the weak nuclear force. W⁺, W⁻ (charge-changing), Z⁰ (neutral). Mass ~80–91 GeV/c².\n\n---", "keywords": ["complete", "glossary", "every", "term", "defined", "alpha decay", "beta decay", "gamma", "half-life", "activity", "binding energy", "semf", "shell model", "valley of stability", "strong force", "neutrino", "quantum tunnelling", "u-238", "tc-99m", "pet", "fission", "fusion", "reactor", "radiation", "dose", "q-value", "parity", "secular equilibrium", "isotope", "pairing", "dating", "applications", "conservation", "historical", "exam", "radioactive decay", "forces"], "source": "Part 2"}, {"heading": "Definitional Questions", "body": "**Q: What is the difference between an isotope and an isobar?**\nIsotopes have the same Z (same element) but different N. Isobars have the same A but different Z (different elements). For example, ¹⁴C and ¹⁴N are isobars (both A=14), while ¹²C and ¹⁴C are isotopes (both Z=6).\n\n**Q: What does the \"m\" in Tc-99m mean?**\n\"m\" stands for metastable. It indicates that Tc-99m is an excited nuclear isomer of Tc-99 — it has the same Z and N (43 and 56 respectively) but exists in a higher-energy configuration that decays via gamma emission with a measurable half-life of 6 hours.\n\n**Q: What is the difference between the decay constant and the half-life?**\nThe decay constant λ is the probability of a single nucleus decaying per unit time (s⁻¹). Half-life t½ is the time for half a large sample to decay. They are related by t½ = 0.693/λ. Both characterise the same property of the nuclide — its rate of decay — but are expressed differently.\n\n**Q: What is the difference between absorbed dose (Gy) and equivalent dose (Sv)?**\nAbsorbed dose (Gray) measures energy deposited per unit mass of tissue (J/kg) without regard to radiation type. Equivalent dose (Sievert) multiplies absorbed dose by a radiation weighting factor to account for the different biological effectiveness of different radiations (alpha = 20×, beta/gamma = 1×). You need to know both the energy deposited AND the radiation type to assess biological harm.\n\n**Q: What is the difference between the strong nuclear force and the strong force (QCD)?**\nAt the fundamental level, the strong force (quantum chromodynamics, QCD) acts between quarks via gluon exchange and holds quarks together inside protons and neutrons. The \"strong nuclear force\" between nucleons is a residual effect — analogous to van der Waals forces between molecules being a residual of electrostatic forces. At nuclear scales, this residual strong force is mediated by meson (pion) exchange (Yukawa potential) and is what binds nucleons in the nucleus.\n\n---", "keywords": ["definitional", "questions", "gamma", "half-life", "activity", "strong force", "tc-99m", "radiation", "dose", "isotope", "exam", "forces"], "source": "Part 2"}, {"heading": "Calculation Questions", "body": "**Q: A sample has activity 1200 Bq. After 3 half-lives, what is the activity?**\nAfter each half-life, activity halves. After 3 half-lives: 1200 × (½)³ = 1200/8 = **150 Bq**.\n\n**Q: U-238 has t½ = 4.47 × 10⁹ y. What fraction of a sample remains after 9.0 × 10⁹ years?**\nNumber of half-lives: n = 9.0×10⁹ / 4.47×10⁹ = 2.013 half-lives.\nFraction remaining: (½)^2.013 = 0.247 = **~24.7%**.\n\n**Q: A radioisotope has λ = 5.0 × 10⁻⁴ s⁻¹. What is its half-life?**\nt½ = 0.693 / λ = 0.693 / (5.0×10⁻⁴) = **1386 s ≈ 23.1 minutes**\n\n**Q: The activity of a sample falls from 2400 Bq to 300 Bq in 30 minutes. What is the half-life?**\n2400 → 1200 → 600 → 300 (3 halvings in 30 min) → t½ = 30/3 = **10 minutes**\n\n**Q: How many nuclei are in a sample of ¹³¹I (t½ = 8.0 d) with activity 1.0 MBq?**\nλ = 0.693 / (8.0 × 86400 s) = 0.693 / 691200 = 1.003×10⁻⁶ s⁻¹\nN = A/λ = 1.0×10⁶ / 1.003×10⁻⁶ = **9.97 × 10¹¹ nuclei**\n\n---", "keywords": ["calculation", "questions", "half-life", "activity", "u-238", "isotope"], "source": "Part 2"}, {"heading": "Conceptual/Explain Questions", "body": "**Q: Why do we not observe stable nuclei with Z > 83?**\nBeyond bismuth (Z=83), the Coulomb repulsion between the 83+ protons is so large that no amount of additional neutrons can provide sufficient binding through the strong force to stabilise the nucleus. The strong force is short-range (~3 fm) and saturates (each nucleon interacts only with nearest neighbours), so adding more neutrons provides diminishing returns. Meanwhile, Coulomb repulsion scales as Z(Z−1) and grows without saturation. The mathematical crossover point where stability becomes impossible lies at Z=83 (bismuth).\n\n**Q: Why does the beta decay spectrum being continuous prove the existence of the neutrino?**\nIf beta decay were simply n → p + e⁻, conservation of energy and momentum would require the electron to be emitted with a single, discrete energy (just as alpha particles are). Experimentally, beta electrons have a continuous spectrum from near-zero up to a maximum Q-value. The only way to conserve both energy and momentum while allowing the electron to have variable energy is if a third particle (the neutrino) is emitted, carrying away the remaining energy and momentum. Pauli proposed this in 1930.\n\n**Q: Explain why a small change in alpha decay energy produces such a large change in half-life.**\nAlpha decay proceeds by quantum tunnelling through the Coulomb barrier. The tunnelling probability depends exponentially on the product of (barrier height − particle energy) and barrier width. A small increase in decay energy (say, from 4 MeV to 9 MeV) raises the particle's energy significantly relative to the barrier, making the effective barrier much narrower and reducing the barrier height difference. Since tunnelling probability is exponential in these quantities, a factor-of-2 change in energy produces an exponential — not linear — change in tunnelling probability, and hence half-life. The Geiger-Nuttall law captures this: log₁₀(T½) ∝ 1/√E. This gives 20 orders of magnitude change in half-life for a factor-of-2 change in energy.\n\n**Q: What would happen to nuclear stability if neutrons did not exist?**\nA nucleus made only of protons would be immediately destroyed by Coulomb repulsion — the strong force between two protons at 1 fm (~100× electromagnetic at that distance) could briefly bind them, but the net force is repulsive because the Coulomb repulsion is long-range and prevents stable multi-proton configurations. Only hydrogen-1 (a single proton, the lone exception with no neutrons) is stable with Z but no N. Even helium-2 (two protons, diproton) is not stable. Without neutrons, chemistry as we know it could not exist — only hydrogen would form stable atoms.\n\n**Q: Why are nuclear properties unaffected by chemical bonding?**\nChemical bonding involves electron rearrangements at energies of ~1–10 eV. Nuclear transitions involve energy scales of ~1 MeV (1,000,000 eV) or more — six orders of magnitude larger. The nucleus is also far smaller than atomic/molecular dimensions (~10⁻¹⁵ m vs. ~10⁻¹⁰ m for atoms). The electromagnetic fields of chemical bonds are entirely negligible compared to nuclear potential energies. Even electron capture (EC) is influenced only very slightly by chemical state (measurable only with very precise experiments using exotic electron-poor ions), and this represents an extreme case — regular alpha/beta/gamma decay rates are completely independent of chemistry.\n\n**Q: What is the significance of iron-56 being at the peak of the BE/A curve?**\n⁵⁶Fe represents the most energetically stable nucleus possible. No nuclear reaction involving iron-56 can release energy — both fusion (⁵⁶Fe + something → heavier product with lower BE/A) and fission (⁵⁶Fe → lighter fragments with lower BE/A) require energy input. In stellar physics, when a massive star fuses progressively heavier elements up to iron, it can no longer release energy from fusion. This loss of energy production causes the star's core to collapse — triggering a supernova. Iron is thus the \"ash\" of stellar nucleosynthesis and the endpoint of energy-releasing fusion in stars.\n\n---", "keywords": ["conceptual", "explain", "questions", "alpha decay", "beta decay", "gamma", "half-life", "activity", "binding energy", "strong force", "neutrino", "quantum tunnelling", "fission", "fusion", "radiation", "dose", "q-value", "conservation", "forces"], "source": "Part 2"}, {"heading": "\"How do we know\" Questions", "body": "**Q: How do scientists know which decay mode an isotope uses?**\nExperimentally by: (1) measuring the emitted radiation type (alpha spectrometry for discrete alpha peaks, beta spectrometry for continuous spectra, gamma spectrometry for gamma photon energies); (2) measuring the change in atomic number (Z) of the daughter using mass spectrometry or chemical analysis; (3) calculating the Q-value from mass data — if Q > 0 for a given mode, it is energetically possible; (4) using the N-Z chart to predict the mode from position relative to the valley of stability.\n\n**Q: How was the nucleus itself discovered?**\nRutherford's gold foil experiment (1909–1911, performed by Geiger and Marsden). Alpha particles fired at gold foil mostly passed through but a small fraction were deflected at large angles — some even backwards. This could only be explained if the positive charge and most of the mass were concentrated in a tiny central nucleus (~10⁻¹⁴ m), rather than spread uniformly through the atom (as Thomson's \"plum pudding\" model assumed). The nuclear model replaced the plum pudding model.\n\n**Q: How do we know magic numbers are real?**\nMultiple independent lines of evidence: (1) Elements with magic Z have anomalously many stable isotopes (tin Z=50 has 10; its neighbours have 2); (2) Nuclei with magic N or Z have higher BE/A than SEMF predicts; (3) Nuclei with magic N or Z have higher energy to their first excited state (harder to excite); (4) Nuclear radii show kinks at magic numbers; (5) Neutron capture cross-sections drop sharply at magic N; (6) Doubly magic nuclei (e.g., ⁴He, ¹⁶O) are especially abundant in nature.\n\n---", "keywords": ["know", "questions", "alpha decay", "activity", "binding energy", "semf", "shell model", "valley of stability", "radiation", "dose", "q-value", "isotope", "historical", "radioactive decay"], "source": "Part 2"}, {"heading": "Application Questions", "body": "**Q: Why is Tc-99m preferred over other gamma emitters in nuclear medicine?**\nMultiple properties combine: (1) Pure gamma emitter — no alpha or beta particles to cause unnecessary tissue irradiation; (2) t½ = 6 hours — short enough to minimise patient dose (most of it decays within 2–3 days), long enough to complete imaging procedures; (3) Gamma energy = 140 keV — ideal for gamma cameras (energetic enough to escape the body, low enough for efficient detection and collimation); (4) Produced on-site from Mo-99 generators (no need for on-site cyclotron); (5) Versatile chemistry — Tc can be attached to many different molecules targeting different organs.\n\n**Q: Why can't we use Tc-99m for treating cancer the way I-131 is used for thyroid cancer?**\nTreatment requires the radiation to kill cells in the target tissue. Tc-99m emits only gamma rays, which pass through the body without depositing much energy locally. I-131 emits beta particles (range ~1 mm in tissue) that deposit all their energy nearby, killing thyroid cells. Beta radiation is effective for therapy; gamma radiation is better suited for imaging. The thyroid naturally concentrates iodine, so I-131 specifically targets thyroid tissue, enabling selective treatment.\n\n**Q: How does a Mo-99/Tc-99m generator work?**\nMo-99 (t½ = 66 h) is absorbed onto an alumina (Al₂O₃) column inside the generator. Mo-99 decays to Tc-99m. When saline solution is passed through the column (called \"milking\"), Tc-99m is eluted (washed out) because it has different chemistry and adheres less strongly to the column than Mo. The Mo-99 stays behind and continues producing more Tc-99m. The generator can be milked approximately every 24 hours for ~2 weeks (the Mo-99 is depleted after ~10 half-lives). The system is in transient equilibrium.\n\n---", "keywords": ["application", "questions", "gamma", "half-life", "activity", "tc-99m", "radiation", "dose", "secular equilibrium", "applications"], "source": "Part 2"}, {"heading": "Trap 1: Confusing α emission with β decay for heavy nuclei", "body": "**Trap:** \"Radon-222 has too many neutrons. It should undergo β⁻ decay.\"\n**Correct answer:** Heavy nuclei (Z > 83, A > 200) preferentially undergo **alpha decay** even if they appear neutron-rich. Alpha decay simultaneously reduces both N and Z, moving toward the valley more effectively for heavy nuclei. The overall N/Z ratio after α decay may still move toward the valley because both Z and N decrease.", "keywords": ["trap", "confusing", "emission", "decay", "heavy", "nuclei", "alpha decay", "beta decay", "valley of stability", "radiation", "n/z", "exam"], "source": "Part 2"}, {"heading": "Trap 2: Forgetting the 1.022 MeV threshold for β⁺", "body": "**Trap:** \"A nucleus with Q = 0.8 MeV for β⁺ decay will undergo β⁺ decay.\"\n**Correct:** Q = 0.8 MeV < 1.022 MeV. β⁺ decay is **not possible**. The nucleus will undergo **electron capture** instead, which has no minimum Q threshold (as long as Q > 0).", "keywords": ["trap", "forgetting", "022", "mev", "threshold", "beta decay", "exam"], "source": "Part 2"}, {"heading": "Trap 3: Thinking half-life depends on temperature or age", "body": "**Trap:** \"If you heat a radioactive sample, it decays faster.\"\n**Correct:** Half-life is **completely independent** of temperature, pressure, and chemical environment. Nuclear energy scales (~MeV) are millions of times larger than thermal energies (~kT ~0.025 eV at room temperature).", "keywords": ["trap", "thinking", "half", "life", "depends", "temperature", "age", "half-life", "dose", "exam"], "source": "Part 2"}, {"heading": "Trap 4: Misidentifying what \"above\" and \"below\" the valley means", "body": "**Trap:** \"A nucleus with N/Z > 1 is below the valley of stability.\"\n**Correct:** N/Z > 1 means MORE neutrons than protons. On an N-Z plot, this is **above** the N=Z line, which means **above** the valley (for light elements where valley ≈ N=Z). Such nuclei decay by β⁻. BELOW the valley means too few neutrons (proton-rich) → β⁺ or EC.", "keywords": ["trap", "misidentifying", "valley", "means", "beta decay", "valley of stability", "n/z", "exam"], "source": "Part 2"}, {"heading": "Trap 5: Applying N=Z rule to heavy elements", "body": "**Trap:** \"Lead-208 has N/Z ≈ 1.54 — it should be unstable because N/Z ≠ 1.\"\n**Correct:** The N=Z stability rule applies only to **light elements (Z ≤ 20)**. For heavy elements, the optimal N/Z is significantly above 1 (up to ~1.5 for lead). Pb-208 is doubly magic and extremely stable despite its high N/Z.", "keywords": ["trap", "applying", "rule", "heavy", "elements", "n/z", "exam"], "source": "Part 2"}, {"heading": "Trap 6: Forgetting that gamma decay changes neither Z nor A", "body": "**Trap:** \"When Tc-99m decays to Tc-99 by gamma emission, its mass number changes.\"\n**Correct:** Gamma emission releases energy (photons) but does NOT change A or Z. Tc-99m and Tc-99 have the same Z and A — they are nuclear isomers. Only their energy state differs.", "keywords": ["trap", "forgetting", "gamma", "decay", "changes", "neither", "tc-99m", "radiation", "dose", "isotope", "exam"], "source": "Part 2"}, {"heading": "Trap 7: Claiming the SEMF works perfectly", "body": "**Trap:** \"The SEMF accurately predicts binding energies for all nuclei.\"\n**Correct:** The SEMF works to within 1–2 MeV for most nuclei but **systematically underestimates binding energy near magic numbers**, where the nuclear shell model must supplement it. It is also less accurate for very light nuclei (A < 10).", "keywords": ["trap", "claiming", "semf", "works", "perfectly", "binding energy", "shell model", "dose", "exam"], "source": "Part 2"}, {"heading": "Trap 8: Confusing activity with number of nuclei", "body": "**Trap:** \"The sample with the highest activity is the one with the most radioactive nuclei.\"\n**Correct:** Activity A = λN = (0.693/t½) × N. A sample with more nuclei BUT longer half-life can have LOWER activity than a smaller sample of a short-lived isotope. For example, a gram of U-238 has far more nuclei than a microgram of Tc-99m, but the Tc-99m sample has far higher activity.", "keywords": ["trap", "confusing", "activity", "number", "nuclei", "half-life", "u-238", "tc-99m", "isotope", "exam"], "source": "Part 2"}, {"heading": "Trap 9: Thinking all radiation causes the same biological harm", "body": "**Trap:** \"1 Gy of alpha radiation causes the same harm as 1 Gy of gamma radiation.\"\n**Correct:** Absorbed dose in Gy measures energy deposited, not biological harm. Alpha particles have a weighting factor of 20 → 1 Gy of alpha radiation = **20 Sv** of equivalent dose, while 1 Gy of gamma = **1 Sv**. Alpha causes 20× more biological damage per unit energy deposited.", "keywords": ["trap", "thinking", "radiation", "causes", "biological", "harm", "alpha decay", "dose", "exam"], "source": "Part 2"}, {"heading": "Trap 10: Forgetting that decay chains involve alternating alpha and beta decays", "body": "**Trap:** \"All steps in the U-238 decay chain are alpha decays.\"\n**Correct:** The U-238 chain involves **8 alpha + 6 beta-minus decays**. After several alpha decays push the nucleus neutron-rich (above the valley), beta-minus decays correct the N/Z ratio. The alternation reflects the curved shape of the valley.", "keywords": ["trap", "forgetting", "decay", "chains", "involve", "alternating", "alpha", "beta", "decays", "alpha decay", "beta decay", "valley of stability", "u-238", "radiation", "n/z", "exam"], "source": "Part 2"}, {"heading": "Trap 11: Claiming Be/A of iron is exactly 8.79 MeV", "body": "**Trap:** \"Fe-56 has BE/A = 8.79 MeV exactly.\"\n**Note:** 8.79 MeV/nucleon is the experimental value for ⁵⁶Fe. The SEMF gives ~8.73 MeV/nucleon for this nucleus — slightly different because the SEMF underestimates near magic numbers. Accept either value in context; specify which you're using.", "keywords": ["trap", "claiming", "iron", "exactly", "mev", "activity", "binding energy", "semf", "shell model", "exam"], "source": "Part 2"}, {"heading": "Trap 12: Applying the age formula incorrectly (using N instead of A)", "body": "**Trap:** In t = (t½/ln2) × ln(A₀/A), substituting number of nuclei for activity.\n**Correct:** The formula works for EITHER: t = (t½/ln2) × ln(N₀/N) OR t = (t½/ln2) × ln(A₀/A). Since A = λN and λ cancels, both give the same result. Do NOT mix — if you use N₀ in the numerator, use N in the denominator (not A).\n\n---\n\n*End of Chapter 8 AI Reference Document — Part 2*\n\n*Use alongside Part 1 for complete coverage. Together, these documents can answer any question from Chapter 8 of Nuclear Instability and Radioactive Decay.*", "keywords": ["trap", "applying", "age", "formula", "incorrectly", "using", "instead", "half-life", "activity", "exam", "radioactive decay", "nuclear instability"], "source": "Part 2"}];

// Common question words that should not count heavily in heading matches
const QUESTION_WORDS = new Set(['what','how','why','when','where','who','which','does','did','do','can','could','would','should','will','is','are','was','were','am','be','been','being','have','has','had','get','got','explain','describe','tell','give']);

function retrieveRelevantChunks(question, maxChunks = 5) {
    const lowerQ = question.toLowerCase();
    const qWords = lowerQ.split(/\s+/).filter(w => w.length > 2);
    const qWordsNoQuestions = qWords.filter(w => !QUESTION_WORDS.has(w));
    
    const scores = TUTOR_KNOWLEDGE_BASE.map((chunk, idx) => {
        let score = 0;
        const headingLower = chunk.heading.toLowerCase();
        const bodyLower = chunk.body.toLowerCase();
        
        // Heading match — high weight, but ignore common question words
        for (const w of qWordsNoQuestions) {
            if (headingLower.includes(w)) score += 10;
        }
        // Bonus if heading contains a multi-word phrase from the question
        for (let i = 0; i < qWordsNoQuestions.length - 1; i++) {
            const phrase = qWordsNoQuestions[i] + ' ' + qWordsNoQuestions[i+1];
            if (headingLower.includes(phrase)) score += 15;
        }
        
        // Keyword match
        for (const kw of chunk.keywords) {
            const kwLower = kw.toLowerCase();
            for (const w of qWords) {
                if (kwLower.includes(w) || w.includes(kwLower)) score += 6;
            }
            // Multi-word keyword bonus
            for (let i = 0; i < qWords.length - 1; i++) {
                const phrase = qWords[i] + ' ' + qWords[i+1];
                if (kwLower.includes(phrase)) score += 10;
            }
        }
        
        // Body match — increased weight for definitional content
        for (const w of qWords) {
            if (bodyLower.includes(w)) score += 2;
        }
        
        // Exact phrase bonus in body
        for (let i = 0; i < qWords.length - 1; i++) {
            const phrase = qWords[i] + ' ' + qWords[i+1];
            if (bodyLower.includes(phrase)) score += 5;
        }
        
        // Exact full question bonus
        if (bodyLower.includes(lowerQ)) score += 25;
        
        // Boost synthetic overview chunks slightly for broad questions
        if (chunk.source === 'Synthesis' && chunk.heading.startsWith('Overview:')) {
            score *= 1.2;
        }
        
        return { idx, score };
    });
    scores.sort((a, b) => b.score - a.score);
    const top = scores.slice(0, maxChunks).filter(s => s.score > 0);
    return top.map(s => TUTOR_KNOWLEDGE_BASE[s.idx]);
}

function buildSystemPrompt(chunks) {
    let context = chunks.map((c, i) => `--- REFERENCE SECTION ${i+1}: ${c.heading} (${c.source}) ---\n${c.body}`).join('\n\n');
    return `You are Eddy, a physics tutor for Chapter 8: Nuclear Instability and Radioactive Decay.\n\nAnswer the student's question using the reference material provided below as your primary source. If the reference material does not fully cover the answer, you may supplement with general physics knowledge about nuclear decay, but always stay within the scope of Chapter 8 and do not make up specific facts, numbers, or formulas that are not in the material.\n\nCRITICAL: Use LaTeX math formatting for ALL equations. Use \$...\$ for inline math and \$\$...\$\$ for display equations. Examples:\n- Inline: The decay law is \$N(t) = N_0 e^{{-\lambda t}}\$\n- Display: \$\$Q = (m_{{\text{{parent}}}} - m_{{\text{{daughter}}}} - m_{{\alpha}}) \times 931.5\ \text{{MeV/u}}\$\$\n\nUse proper LaTeX commands: \times, \frac{{a}}{{b}}, \sqrt{{x}}, \lambda, \alpha, \beta, \gamma, \nu, \bar{{\nu}}, \pm, \approx, \rightarrow, \propto, subscripts with _, superscripts with ^, text mode with \text{{}}.\n\nBe concise but thorough. Format your response in clean paragraphs. Do not make up facts.\n\nREFERENCE MATERIAL:\n\n${context}`;
}
